        public void ExecuteGoldCustom(string mode)
        {
            double v; var t = (AmountText ?? "").Trim().Replace(",", "");
            if (!double.TryParse(t, NumberStyles.Float, CultureInfo.InvariantCulture, out v) || v < 0) { ShowResult(false, "اكتب مبلغ صحيح"); return; }
