        static string ItemGroup(string type, bool food, out string ar)
        {
            switch (type)
            {
                case "Horse": ar = "خيل"; return "horse";
                case "HorseHarness": ar = "سرج"; return "horse";
                case "OneHandedWeapon": ar = "سلاح بإيد"; return "weapon";
                case "TwoHandedWeapon": ar = "سلاح بإيدين"; return "weapon";
                case "Polearm": ar = "رمح"; return "weapon";
                case "Arrows": ar = "سهام"; return "weapon";
                case "Bolts": ar = "سهام مستعرض"; return "weapon";
                case "Shield": ar = "درع إيد"; return "weapon";
                case "Bow": ar = "قوس"; return "weapon";
                case "Crossbow": ar = "قوس مستعرض"; return "weapon";
                case "Thrown": ar = "رمي"; return "weapon";
                case "Sling": case "SlingStones": ar = "مقلاع"; return "weapon";
                case "HeadArmor": ar = "خوذة"; return "armor";
                case "BodyArmor": ar = "درع صدر"; return "armor";
                case "LegArmor": ar = "جزمة"; return "armor";
                case "HandArmor": ar = "جوانتي"; return "armor";
                case "Cape": ar = "عباية"; return "armor";
                case "ChestArmor": ar = "درع"; return "armor";
                case "Animal": ar = "مواشي"; return "goods";
                case "Goods": ar = food ? "أكل" : "بضاعة"; return food ? "food" : "goods";
            }
            ar = type; return "other";
        }
        void LoadItems()
        {
            var list = new List<WItem>();
            try
            {
                var it = AccessTools.TypeByName("TaleWorlds.Core.ItemObject");
                var all = Pv(AccessTools.TypeByName("TaleWorlds.Core.Items"), "All") as IEnumerable;
                if (all == null && it != null)
                {
                    var mgrT = AccessTools.TypeByName("TaleWorlds.ObjectSystem.MBObjectManager"); var mgr = Pv(mgrT, "Instance");
                    var gl = mgrT == null ? null : mgrT.GetMethods().FirstOrDefault(m => m.Name == "GetObjectTypeList" && m.IsGenericMethodDefinition && m.GetParameters().Length == 0);
                    if (gl != null && mgr != null) all = gl.MakeGenericMethod(it).Invoke(mgr, null) as IEnumerable;
                }
                if (all != null)
                    foreach (var o in all)
                    {
                        var id = Sv(Pv(o, "StringId")); var name = Sv(Pv(o, "Name"));
                        if (id.Length == 0 || name.Length == 0 || id.StartsWith("_") || Bv(o, "NotMerchandise") && !Bv(o, "IsFood")) continue;
                        string ar; var g = ItemGroup(Sv(Pv(o, "Type")), Bv(o, "IsFood"), out ar);
                        if (g == "other") continue;
                        int v = 0; try { v = Convert.ToInt32(Pv(o, "Value")); } catch { }
                        list.Add(new WItem { Id = id, Name = name, Group = g, TypeAr = ar, Value = v });
                    }
            }
            catch (Exception e) { Log.W("AdminMenu.LoadItems: " + (e.InnerException ?? e).Message); }
            items = list.OrderBy(x => x.Group).ThenBy(x => x.Name).ToList();
            RefreshItems();
        }
        void RefreshItems()
        {
            var q = (ItemSearch ?? "").Trim();
            var list = items.Where(x => (itemType == "all" || x.Group == itemType) && (q.Length == 0 || x.Name.IndexOf(q, StringComparison.OrdinalIgnoreCase) >= 0)).ToList();
            var pages = Math.Max(1, (list.Count + IPage - 1) / IPage);
            if (itemPage >= pages) itemPage = pages - 1; if (itemPage < 0) itemPage = 0;
            ItemMatches.Clear();
            foreach (var x in list.Skip(itemPage * IPage).Take(IPage))
            {
                var row = new AdminRowVM(x.Id, x.Name, x.TypeAr + "  •  " + x.Value.ToString("N0", CultureInfo.InvariantCulture) + " دينار", r => { selItem = r.Key; RefreshItems(); }, null, null);
                row.IsSelected = x.Id == selItem; ItemMatches.Add(row);
            }
            ItemPageText = (itemPage + 1) + " / " + pages;
            ITAll = itemType == "all"; ITFood = itemType == "food"; ITGoods = itemType == "goods"; ITWeapon = itemType == "weapon"; ITArmor = itemType == "armor"; ITHorse = itemType == "horse";
            var s = items.FirstOrDefault(x => x.Id == selItem);
            SelItemText = s == null ? (items.Count == 0 ? "مش قادر أقرا الحاجات من الحملة" : "اختار حاجة من القايمة  (" + list.Count + " نتيجة)") : s.Name + "  —  " + s.TypeAr + "  •  " + s.Value.ToString("N0", CultureInfo.InvariantCulture) + " دينار";
        }
        public void ExecuteItemType(string t) { itemType = t; itemPage = 0; RefreshItems(); }
        public void ExecuteItemPrev() { itemPage--; RefreshItems(); }
        public void ExecuteItemNext() { itemPage++; RefreshItems(); }
        void ItemChange(int sign)
        {
            var x = items.FirstOrDefault(i => i.Id == selItem);
            if (x == null) { ShowResult(false, "اختار الحاجة الأول"); return; }
            var n = CountFrom(ItemCountText, 10000); if (n == 0) return;
            Run((sign > 0 ? "حط " : "شيل ") + n + " " + x.Name, "itemset " + Target + " " + x.Id + " " + (sign > 0 ? "+" : "-") + n, sign < 0);
        }
        public void ExecuteItemGive() { ItemChange(1); }
        public void ExecuteItemTake() { ItemChange(-1); }

