// =====================================================================================
//  system/AdminHost.cs — نظام إدارة اللاعبين (جزء السيرفر)
//  ملف نظام: الاستوديو بيكتبه من جديد مع كل بناء. متعدّلش فيه — أي تعديل هيتمسح.
//
//  بيشتغل على السيرفر بس (على أجهزة اللاعيبة بيفضل نايم ومش بيعمل حاجة).
//  بيتكلم مع الاستوديو عن طريق ملفات في  C:\ProgramData\Aurelion\Admin :
//    state\players.json     اللاعيبة الأونلاين دلوقتي (بيتكتب كل 3 ثواني)
//    state\server.json      حالة نظام الإدارة على السيرفر
//    state\catalog.json     كل أوامر Coop (تبويب CHEATS) بأسمائها ووصفها
//    known-players.json     كل لاعب دخل السيرفر قبل كده
//    bans.json              قايمة الحظر بتاعتنا (بالاسم والسبب) — منها بيتعمل ملف حظر Coop
//    commands\*.json        أوامر من الاستوديو (طرد / حظر / فك حظر / أمر Coop) — بتتنفذ وتتنقل لـ commands\done
//    audit.jsonl            سجل كل فعل: مين عمل إيه لمين وإمتى (مابيتمسحش)
//    alerts.jsonl           تنبيهات الحاجات الغريبة (غش محتمل)
//    admin-config.json      حدود كشف الغش (الاستوديو بيكتبها)
//  كل التعامل مع Coop واللعبة بالـ reflection، فمش بيعتمد على إصدار معين.
// =====================================================================================
using System;
using System.Collections;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Text;
using HarmonyLib;

namespace Aurelion.Core
{
    public static class AdminHost
    {
        public const int Version = 8;
        static readonly BindingFlags All = BindingFlags.Instance | BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic;

        public static string Root { get { return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.CommonApplicationData), "Aurelion", "Admin"); } }
        static string StateDir { get { return Path.Combine(Root, "state"); } }
        static string CmdDir { get { return Path.Combine(Root, "commands"); } }

        static bool isServer, gaveUp;
        static DateTime nextProbe = DateTime.MinValue, nextSnap = DateTime.MinValue, nextCmd = DateTime.MinValue, nextKnownSave = DateTime.MinValue, nextWorld = DateTime.MinValue;
        static int probes, errors;
        static DateTime nextTime = DateTime.MinValue;
        static object playerManager, terminator, banList, dispatcher, registry;
