        static object Peer(string controllerId)
        {
            try
            {
                var m = playerManager.GetType().GetMethods(All).FirstOrDefault(x => x.Name == "TryGetPeer" && x.GetParameters().Length == 2 && x.GetParameters()[0].ParameterType == typeof(string));
                if (m == null) return null;
                var a = new object[] { controllerId, null };
                var ok = m.Invoke(playerManager, a);
                return ok is bool && (bool)ok ? a[1] : null;
            }
            catch { return null; }
        }

        static void PeerInfo(object peer, out string ip, out int port, out int ping)
        {
            ip = ""; port = 0; ping = -1;
            if (peer == null) return;
            try
            {
                var ep = Get(peer, "EndPoint") ?? Get(peer, "RemoteEndPoint");
                var ipe = (ep ?? peer) as System.Net.IPEndPoint;
                if (ipe != null) { ip = ipe.Address.ToString(); port = ipe.Port; }
                else { var s = Convert.ToString(ep ?? peer); var i = s.LastIndexOf(':'); ip = i > 0 ? s.Substring(0, i) : s; }
                if (ip.StartsWith("::ffff:")) ip = ip.Substring(7);
                var pg = Get(peer, "Ping") ?? Get(peer, "RoundTripTime");
                if (pg != null) ping = Convert.ToInt32(pg, CultureInfo.InvariantCulture);
            }
            catch { }
        }

        static MethodInfo heroFind; static bool heroLogged;
        static object FindHero(string heroId, object player)
        {
            object h = null;
            var heroType = AccessTools.TypeByName("TaleWorlds.CampaignSystem.Hero");
            if (heroType == null) return null;
            if (!string.IsNullOrEmpty(heroId))
            {
                // 1) Hero.Find(stringId) - campaign object manager (heroes made at runtime live here)
                try
                {
                    if (heroFind == null) heroFind = heroType.GetMethods(BindingFlags.Static | BindingFlags.Public).FirstOrDefault(m => m.Name == "Find" && m.GetParameters().Length == 1 && m.GetParameters()[0].ParameterType == typeof(string));
                    if (heroFind != null) h = heroFind.Invoke(null, new object[] { heroId });
                }
                catch { }
                // 2) Coop object manager
                if (h == null) h = CoopObject(heroType, heroId);
                // 3) scan all heroes
                if (h == null) h = Scan(Get(heroType, "AllAliveHeroes") as IEnumerable, heroId) ?? Scan(Get(heroType, "DeadOrDisabledHeroes") as IEnumerable, heroId);
                // 4) MBObjectManager
                if (h == null)
                    try
                    {
                        var mgrType = AccessTools.TypeByName("TaleWorlds.ObjectSystem.MBObjectManager");
                        var mgr = Get(mgrType, "Instance");
                        var gm = mgrType.GetMethods(BindingFlags.Instance | BindingFlags.Public).FirstOrDefault(m => m.Name == "GetObject" && m.IsGenericMethodDefinition && m.GetParameters().Length == 1 && m.GetParameters()[0].ParameterType == typeof(string));
                        h = gm.MakeGenericMethod(heroType).Invoke(mgr, new object[] { heroId });
                    }
                    catch { }
            }
            // 5) through the player's party
            if (h == null && player != null)
            {
                var pid = Convert.ToString(Get(player, "MobilePartyId"));
                if (!string.IsNullOrEmpty(pid))
                {
                    var mpType = AccessTools.TypeByName("TaleWorlds.CampaignSystem.Party.MobileParty");
                    var party = CoopObject(mpType, pid) ?? Scan(Get(mpType, "All") as IEnumerable, pid);
                    if (party != null) h = Get(party, "LeaderHero");
                }
            }
            if (h == null && !heroLogged) { heroLogged = true; Log.W("AdminHost: hero not found for id=" + heroId + " party=" + Convert.ToString(Get(player, "MobilePartyId"))); }
            return h;
        }

        static object Scan(IEnumerable all, string id)
        {
            if (all == null) return null;
            try { foreach (var o in all) if (o != null && Convert.ToString(Get(o, "StringId")) == id) return o; } catch { }
            return null;
        }

        static object coopObjMgr; static MethodInfo coopTryGet;
        static object CoopObject(Type t, string id)
        {
            if (t == null || string.IsNullOrEmpty(id)) return null;
            try
            {
                if (coopObjMgr == null)
                {
                    var it = AccessTools.TypeByName("GameInterface.Services.ObjectManager.IObjectManager");
                    if (it == null) return null;
                    coopObjMgr = Resolve(it.FullName);
                    if (coopObjMgr == null) return null;
                    coopTryGet = it.GetMethods().FirstOrDefault(m => m.Name == "TryGetObject" && m.IsGenericMethodDefinition && m.GetParameters().Length == 2 && m.GetParameters()[0].ParameterType == typeof(string));
                }
                if (coopTryGet == null) return null;
                var args = new object[] { id, null };
                var ok = coopTryGet.MakeGenericMethod(t).Invoke(coopObjMgr, args);
                return ok is bool && (bool)ok ? args[1] : null;
            }
            catch { return null; }
        }

        static MethodInfo getSkill; static IEnumerable skillsAll;
        static bool skillsLogged;
        static IEnumerable AllSkills()
        {
            foreach (var n in new[] { "TaleWorlds.CampaignSystem.Extensions.Skills", "TaleWorlds.Core.Skills" })
            {
                var t = AccessTools.TypeByName(n);
                var a = t == null ? null : Get(t, "All") as IEnumerable;
                if (a != null && a.Cast<object>().Any()) return a;
            }
            try
            {   // MBObjectManager.Instance.GetObjectTypeList<SkillObject>()
                var so = AccessTools.TypeByName("TaleWorlds.Core.SkillObject");
                var mgrType = AccessTools.TypeByName("TaleWorlds.ObjectSystem.MBObjectManager");
                var mgr = Get(mgrType, "Instance");
                var m = mgrType.GetMethods(BindingFlags.Instance | BindingFlags.Public).FirstOrDefault(x => x.Name == "GetObjectTypeList" && x.IsGenericMethodDefinition && x.GetParameters().Length == 0);
                var a = m == null ? null : m.MakeGenericMethod(so).Invoke(mgr, null) as IEnumerable;
                if (a != null && a.Cast<object>().Any()) return a;
            }
            catch { }
            if (!skillsLogged) { skillsLogged = true; Log.W("AdminHost: skills list not found"); }
            return null;
        }

        static Dictionary<string, object> Skills(object hero, out double total)
        {
            total = 0; var d = new Dictionary<string, object>();
            try
            {
                if (skillsAll == null) skillsAll = AllSkills();
                if (getSkill == null) getSkill = hero.GetType().GetMethods(BindingFlags.Instance | BindingFlags.Public).FirstOrDefault(m => m.Name == "GetSkillValue" && m.GetParameters().Length == 1);
                if (skillsAll == null || getSkill == null) return d;
                foreach (var s in skillsAll)
                {
                    var v = Convert.ToDouble(getSkill.Invoke(hero, new[] { s }), CultureInfo.InvariantCulture);
                    d[Convert.ToString(Get(s, "StringId"))] = v; total += v;
                }
            }
            catch { }
            return d;
        }

        static void Snapshot()
        {
            var list = new List<object>();
            var seen = new HashSet<string>();
            var now = DateTime.Now;
            var byIp = new Dictionary<string, List<string>>();
            foreach (var p in Players())
            {
                var cid = Convert.ToString(Get(p, "ControllerId"));
                if (string.IsNullOrEmpty(cid)) continue;
                var peer = Peer(cid);
                if (peer == null) continue;   // registered but not connected
                seen.Add(cid);
                string ip; int port, ping; PeerInfo(peer, out ip, out port, out ping);
                var heroId = Convert.ToString(Get(p, "HeroId"));
                var hero = FindHero(heroId, p);
                var e = new Dictionary<string, object>();
                e["controllerId"] = cid; e["steam64"] = IsSteam64(cid); e["platformName"] = Str(Get(p, "PlatformName"));
                e["heroId"] = heroId; e["ip"] = ip; e["port"] = port; e["ping"] = ping;
                e["clanId"] = Str(Get(p, "ClanId")); e["partyId"] = Str(Get(p, "MobilePartyId"));
                double gold = 0, renown = 0, troops = 0, skillTotal = 0, setCount = 0;
                if (hero != null)
                {
                    e["heroName"] = Str(Get(hero, "Name"));
                    gold = Num(Get(hero, "Gold")); e["gold"] = gold;
                    e["level"] = Num(Get(hero, "Level"));
                    e["hp"] = Num(Get(hero, "HitPoints"));
                    e["isPrisoner"] = Get(hero, "IsPrisoner") is bool && (bool)Get(hero, "IsPrisoner");
                    var clan = Get(hero, "Clan");
                    if (clan != null)
                    {
                        e["clan"] = Str(Get(clan, "Name")); renown = Num(Get(clan, "Renown")); e["renown"] = renown;
                        e["tier"] = Num(Get(clan, "Tier")); e["influence"] = Num(Get(clan, "Influence"));
                        var k = Get(clan, "Kingdom"); e["kingdom"] = k == null ? "" : Str(Get(k, "Name")); e["kingdomId"] = k == null ? "" : Str(Get(k, "StringId"));
                        if (Str(e["clanId"]).Length == 0) e["clanId"] = Str(Get(clan, "StringId"));
                        var names = new List<object>(); var sids = new List<object>();
                        var sets = Get(clan, "Settlements") as IEnumerable;
                        if (sets != null) foreach (var s in sets) { names.Add(Str(Get(s, "Name"))); sids.Add(Str(Get(s, "StringId"))); }
                        setCount = names.Count; e["settlements"] = names; e["settlementIds"] = sids;
                    }
                    var party = Get(hero, "PartyBelongedTo");
                    if (party != null)
                    {
                        if (Str(e["partyId"]).Length == 0) e["partyId"] = Str(Get(party, "StringId"));
                        troops = Num(Get(Get(party, "MemberRoster"), "TotalManCount")); e["troops"] = troops;
                        e["prisoners"] = Num(Get(Get(party, "PrisonRoster"), "TotalManCount"));
                    }
                    e["skills"] = Skills(hero, out skillTotal); e["skillTotal"] = skillTotal;
                }
                Online o;
                if (!online.TryGetValue(cid, out o))
                {
                    o = new Online { Ip = ip, Since = now }; online[cid] = o;
                    Audit("system", "النظام", "join", cid, Str(e.ContainsKey("heroName") ? e["heroName"] : e["platformName"]), "", true, "دخل السيرفر من " + ip);
                    TestGate(cid, ip, Str(e.ContainsKey("heroName") ? e["heroName"] : e["platformName"]));
                }
                o.Ip = ip;
                e["since"] = Iso(o.Since);
                var cur = new Snap { At = DateTime.UtcNow, Gold = gold, Renown = renown, Troops = troops, Skills = skillTotal, Settlements = setCount };
                if (hero != null) { CheckCheat(cid, e, o.Last, cur); o.Last = cur; }
                Remember(cid, e);
                if (ip.Length > 0) { List<string> l; if (!byIp.TryGetValue(ip, out l)) byIp[ip] = l = new List<string>(); l.Add(cid); }
                list.Add(e);
            }
            foreach (var gone in online.Keys.Where(k => !seen.Contains(k)).ToList())
            {
                Audit("system", "النظام", "leave", gone, KnownName(gone), "", true, "خرج من السيرفر");
                authed.Remove(gone);
                online.Remove(gone); MarkSeen(gone);
            }
            if (cfg.CheatsEnabled && cfg.SameIpAlert)
                foreach (var kv in byIp.Where(x => x.Value.Count > 1))
                    Alert("same-ip", string.Join(",", kv.Value), "أكتر من حساب من نفس الـIP", kv.Value.Count + " حسابات أونلاين من " + kv.Key + ": " + string.Join(" ، ", kv.Value.Select(KnownName)));
            var d = new Dictionary<string, object>();
            lastList = list; gwPlayers = list.Count;
            FlushPendingUi();
            d["updated"] = Iso(now); d["serverRunning"] = true; d["players"] = list;
            WriteJson(Path.Combine(StateDir, "players.json"), d);
        }

        static void CheckCheat(string cid, Dictionary<string, object> e, Snap a, Snap b)
        {
            if (!cfg.CheatsEnabled || a == null) return;
            DateTime until;
            if (ignoreUntil.TryGetValue(cid, out until) && DateTime.UtcNow < until) return;
            var mins = Math.Max(1.0 / 60, (b.At - a.At).TotalMinutes);
            var name = Str(e.ContainsKey("heroName") ? e["heroName"] : cid);
            Action<string, string, double, double, string> chk = (kind, label, before, after, unit) =>
            {
                double limit = kind == "gold" ? cfg.GoldPerMin : kind == "renown" ? cfg.RenownPerMin : kind == "troops" ? cfg.TroopsPerMin : kind == "skills" ? cfg.SkillsPerMin : cfg.SettlementsPerMin;
                var diff = after - before;
                if (limit > 0 && diff > 0 && diff / mins > limit)
                    Alert(kind, cid, label + " زاد بسرعة غريبة", name + ": " + label + " زاد " + diff.ToString("N0", CultureInfo.InvariantCulture) + " " + unit + " في " + Math.Max(1, (int)Math.Round(mins * 60)) + " ثانية (من " + before.ToString("N0", CultureInfo.InvariantCulture) + " لـ " + after.ToString("N0", CultureInfo.InvariantCulture) + ")");
            };
            chk("gold", "الفلوس", a.Gold, b.Gold, "دينار");
            chk("renown", "الشهرة", a.Renown, b.Renown, "");
            chk("troops", "عدد الجنود", a.Troops, b.Troops, "جندي");
            chk("skills", "مجموع المهارات", a.Skills, b.Skills, "نقطة");
            chk("settlements", "عدد الممتلكات", a.Settlements, b.Settlements, "");
        }

        static void Alert(string kind, string cid, string title, string text)
        {
            var key = kind + "|" + cid; DateTime last;
            if (alertSeen.TryGetValue(key, out last) && (DateTime.UtcNow - last).TotalMinutes < 10) return;
            alertSeen[key] = DateTime.UtcNow;
            var d = new Dictionary<string, object>();
            d["time"] = Iso(DateTime.Now); d["kind"] = kind; d["target"] = cid; d["targetName"] = cid.Contains(",") ? "" : KnownName(cid); d["title"] = title; d["text"] = text;
            AppendLine(Path.Combine(Root, "alerts.jsonl"), d);
        }

        // ------------------------------------------------------------------ players seen before
        static void LoadKnown()
        {
            known = ReadJson(Path.Combine(Root, "known-players.json"));
        }
        static void SaveKnown() { WriteJson(Path.Combine(Root, "known-players.json"), known); knownDirty = false; }
        static void Remember(string cid, Dictionary<string, object> e)
        {
            object o; Dictionary<string, object> k;
            if (known.TryGetValue(cid, out o) && o is Dictionary<string, object>) k = (Dictionary<string, object>)o;
            else { k = new Dictionary<string, object>(); k["firstSeen"] = Iso(DateTime.Now); known[cid] = k; knownDirty = true; }
            foreach (var f in new[] { "platformName", "heroId", "heroName", "clan", "kingdom", "ip" })
            {
                object v; if (!e.TryGetValue(f, out v) || v == null || Convert.ToString(v).Length == 0) continue;
                object old; if (!k.TryGetValue(f, out old) || !Equals(Convert.ToString(old), Convert.ToString(v))) { k[f] = v; knownDirty = true; }
            }
            object ipo; var ip = e.TryGetValue("ip", out ipo) ? Convert.ToString(ipo) : "";
            if (ip.Length > 0)
            {
                var ips = (k.ContainsKey("ips") ? k["ips"] as IEnumerable : null);
                var l = ips == null ? new List<object>() : ips.Cast<object>().ToList();
                if (!l.Any(x => Convert.ToString(x) == ip)) { l.Add(ip); k["ips"] = l; knownDirty = true; }
            }
            k["lastSeen"] = Iso(DateTime.Now);
            foreach (var f in new[] { "gold", "renown", "troops", "skillTotal" }) { object v; if (e.TryGetValue(f, out v)) k[f] = v; }
        }
        static void MarkSeen(string cid) { object o; if (known.TryGetValue(cid, out o) && o is Dictionary<string, object>) ((Dictionary<string, object>)o)["lastSeen"] = Iso(DateTime.Now); knownDirty = true; }
        static string KnownName(string cid)
        {
            object o; if (known != null && known.TryGetValue(cid, out o) && o is Dictionary<string, object>)
            {
                var k = (Dictionary<string, object>)o; object n;
                if (k.TryGetValue("heroName", out n) && Convert.ToString(n).Length > 0) return Convert.ToString(n);
                if (k.TryGetValue("platformName", out n) && Convert.ToString(n).Length > 0) return Convert.ToString(n);
            }
            return cid;
        }

        // ------------------------------------------------------------------ commands from the Studio
        static void ProcessCommands()
        {
            if (!Directory.Exists(CmdDir)) return;
            foreach (var f in Directory.GetFiles(CmdDir, "*.json").OrderBy(x => x, StringComparer.Ordinal).Take(20))
            {
                Dictionary<string, object> c = null;
                try { c = Mj.Parse(File.ReadAllText(f, Encoding.UTF8)) as Dictionary<string, object>; }
                catch (IOException) { continue; }   // still being written
                catch (Exception e) { Log.W("bad command file " + f + ": " + e.Message); }
                try { File.Move(f, Path.Combine(CmdDir, "done", Path.GetFileName(f))); } catch { try { File.Delete(f); } catch { } }
                if (c == null) continue;
                Execute(c);
            }
        }

        static void Execute(Dictionary<string, object> c)
        {
            var id = Mj.S(c, "id", ""); var by = Mj.S(c, "by", "owner"); var byName = Mj.S(c, "byName", "المالك");
            var action = Mj.S(c, "action", ""); var target = Mj.S(c, "target", ""); var reason = Mj.S(c, "reason", "");
            var tname = target.Length > 0 ? KnownName(target) : "";
            bool ok = false; string output;
            try
            {
                switch (action)
                {
                    case "kick":
                        output = Kick(target, reason.Length > 0 ? reason : "اتطردت من السيرفر بواسطة الإدارة", out ok); break;
                    case "ban":
                        SyncBans(true);
                        output = banList == null ? "قايمة الحظر بتاعة Coop مش متاحة" : CheckBanned(target);
                        ok = banList != null && output.StartsWith("✓");
                        if (online.ContainsKey(target)) { bool k; Kick(target, "اتحظرت من السيرفر" + (reason.Length > 0 ? ": " + reason : ""), out k); output += " — واتطرد"; }
                        break;
                    case "unban":
                        SyncBans(true); ok = true; output = "✓ اتفك الحظر"; break;
                    case "run":
                        var cmd = Mj.S(c, "command", "");
                        var args = new List<string>();
                        object ao; if (c.TryGetValue("args", out ao) && ao is IEnumerable && !(ao is string)) foreach (var a in (IEnumerable)ao) args.Add(Convert.ToString(a, CultureInfo.InvariantCulture));
                        output = Run(cmd, args, out ok);
                        if (target.Length > 0) ignoreUntil[target] = DateTime.UtcNow.AddSeconds(60);
                        action = "run:" + cmd;
                        break;
                    case "gold-add":
                        {   // args: heroId, delta  -> set_gold_state heroId (current + delta)
                            var ga = new List<string>();
                            object go; if (c.TryGetValue("args", out go) && go is IEnumerable && !(go is string)) foreach (var a in (IEnumerable)go) ga.Add(Convert.ToString(a, CultureInfo.InvariantCulture));
                            if (ga.Count < 2) { output = "ناقص بيانات"; break; }
                            var hero = FindHero(ga[0], null);
                            if (hero == null) { output = "البطل مش موجود: " + ga[0]; break; }
                            double delta; double.TryParse(ga[1], NumberStyles.Float, CultureInfo.InvariantCulture, out delta);
                            var cur = Num(Get(hero, "Gold"));
                            var nv = Math.Max(0, Math.Round(cur + delta));
                            output = Run("coop.debug.hero.set_gold_state", new List<string> { ga[0], nv.ToString("0", CultureInfo.InvariantCulture) }, out ok);
                            output = (ok ? cur.ToString("N0", CultureInfo.InvariantCulture) + " ← " + nv.ToString("N0", CultureInfo.InvariantCulture) + "  " : "") + output;
                            if (target.Length > 0) ignoreUntil[target] = DateTime.UtcNow.AddSeconds(60);
                            break;
                        }
                    case "refresh-catalog":
                        WriteCatalog(); ok = true; output = "✓"; break;
                    default:
                        output = "أمر مش معروف: " + action; break;
                }
            }
            catch (Exception e) { output = "خطأ: " + (e.InnerException ?? e).Message; ok = false; }
            Audit(by, byName, action, target, tname, reason, ok, output, id, c);
        }

        static string Kick(string cid, string reason, out bool ok)
        {
            ok = false;
            var peer = Peer(cid);
            if (peer == null) return "اللاعب مش أونلاين";
            try
            {
                var m = terminator.GetType().GetMethods(All).FirstOrDefault(x => x.Name == "Disconnect" && x.GetParameters().Length == 2);
                if (m == null) throw new MissingMethodException("Disconnect");
                m.Invoke(terminator, new[] { peer, reason });
            }
            catch (Exception e)
            {   // fall back to the network peer itself
                Log.W("kick via terminator failed: " + (e.InnerException ?? e).Message);
                var d = peer.GetType().GetMethods(BindingFlags.Instance | BindingFlags.Public).FirstOrDefault(x => x.Name == "Disconnect" && x.GetParameters().Length == 0);
                if (d == null) return "مقدرتش أطرده: " + (e.InnerException ?? e).Message;
                d.Invoke(peer, null);
            }
            ok = true; return "✓ اتطرد";
        }

        static string Run(string cmd, List<string> args, out bool ok)
        {
            ok = false;
            if (dispatcher == null) return "أوامر Coop مش متاحة";
            var ready = dispatcher.GetType().GetMethod("EnsureReady", All);
            if (ready != null) ready.Invoke(dispatcher, null);
            var ex = dispatcher.GetType().GetMethods(All).FirstOrDefault(x => x.Name == "Execute" && x.GetParameters().Length == 2);
            var r = ex.Invoke(dispatcher, new object[] { cmd, args });
            var found = Get(r, "Found"); var succ = Get(r, "Succeeded"); var outp = Str(Get(r, "Output")); var err = Str(Get(r, "ErrorCode"));
            if (found is bool && !(bool)found) return "الأمر مش موجود: " + cmd;
            ok = succ is bool ? (bool)succ : err.Length == 0;
            return (ok ? "✓ " : "✗ ") + outp + (err.Length > 0 ? " [" + err + "]" : "");
        }

        // towns / castles / villages and kingdoms, for the Studio's pickers (owner actions)
        static void WriteWorld()
        {
            try
            {
                var sets = new List<object>();
                var st = AccessTools.TypeByName("TaleWorlds.CampaignSystem.Settlements.Settlement");
                var all = Get(st, "All") as IEnumerable;
                if (all != null)
                    foreach (var s in all)
                    {
                        bool town = Get(s, "IsTown") is bool && (bool)Get(s, "IsTown");
                        bool castle = Get(s, "IsCastle") is bool && (bool)Get(s, "IsCastle");
                        bool village = Get(s, "IsVillage") is bool && (bool)Get(s, "IsVillage");
                        if (!town && !castle && !village) continue;
                        var d = new Dictionary<string, object>();
                        d["id"] = Str(Get(s, "StringId")); d["name"] = Str(Get(s, "Name"));
                        d["type"] = town ? "town" : castle ? "castle" : "village";
                        var oc = Get(s, "OwnerClan"); d["owner"] = oc == null ? "" : Str(Get(oc, "Name"));
                        var ok = oc == null ? null : Get(oc, "Kingdom");
                        d["kingdom"] = ok == null ? "" : Str(Get(ok, "Name")); d["kingdomId"] = ok == null ? "" : Str(Get(ok, "StringId"));
                        if (village) { var vc = Get(s, "Village"); var bt = vc == null ? null : Get(vc, "Bound"); d["bound"] = bt == null ? "" : Str(Get(bt, "Name")); }
                        sets.Add(d);
                    }
                var kings = new List<object>();
                var kt = AccessTools.TypeByName("TaleWorlds.CampaignSystem.Kingdom");
                var ka = Get(kt, "All") as IEnumerable;
                if (ka != null)
                    foreach (var k in ka)
                    {
                        if (Get(k, "IsEliminated") is bool && (bool)Get(k, "IsEliminated")) continue;
                        var d = new Dictionary<string, object>();
                        d["id"] = Str(Get(k, "StringId")); d["name"] = Str(Get(k, "Name"));
                        var ld = Get(k, "Leader"); d["leaderId"] = ld == null ? "" : Str(Get(ld, "StringId")); d["leader"] = ld == null ? "" : Str(Get(ld, "Name"));
                        var kid = Mj.S(d, "id", "");
                        d["towns"] = sets.OfType<Dictionary<string, object>>().Count(x => Mj.S(x, "kingdomId", "") == kid && Mj.S(x, "type", "") == "town");
                        d["castles"] = sets.OfType<Dictionary<string, object>>().Count(x => Mj.S(x, "kingdomId", "") == kid && Mj.S(x, "type", "") == "castle");
                        var cl = Get(k, "Clans") as IEnumerable; d["clans"] = cl == null ? 0 : cl.Cast<object>().Count();
                        kings.Add(d);
                    }
                var root = new Dictionary<string, object>();
                root["updated"] = Iso(DateTime.Now); root["settlements"] = sets; root["kingdoms"] = kings;
                WriteJson(Path.Combine(StateDir, "world.json"), root);
            }
            catch (Exception e) { Log.W("AdminHost.WriteWorld: " + (e.InnerException ?? e).Message); }
        }

        static void WriteCatalog()
        {
            try
            {
                var list = new List<object>();
                var descs = new Dictionary<string, Dictionary<string, object>>(StringComparer.OrdinalIgnoreCase);
                var cmds = registry == null ? null : Get(registry, "Commands") as IEnumerable;
                if (cmds != null)
                    foreach (var c in cmds)
                    {
                        var d = new Dictionary<string, object>();
                        var pre = Str(Get(c, "Prefix")); var nm = Str(Get(c, "Name"));
                        d["name"] = pre.Length > 0 ? pre + "." + nm : nm; d["description"] = Str(Get(c, "Description")); d["side"] = Str(Get(c, "Side"));
                        var al = new List<object>();
                        var ea = Get(c, "ExpectedArgs") as IEnumerable;
                        if (ea != null) foreach (var a in ea)
                            {
                                var ad = new Dictionary<string, object>();
                                foreach (var pi in a.GetType().GetProperties(BindingFlags.Instance | BindingFlags.Public)) { try { var v = pi.GetValue(a, null); if (v == null || v is string || v.GetType().IsPrimitive || v is Enum) ad[pi.Name] = v == null ? "" : Convert.ToString(v, CultureInfo.InvariantCulture); } catch { } }
                                ad["text"] = Convert.ToString(a);
                                al.Add(ad);
                            }
                        d["args"] = al;
                        descs[Convert.ToString(d["name"])] = d;
                    }
                var names = new List<string>();
                if (dispatcher != null)
                {
                    var gn = dispatcher.GetType().GetMethod("GetCommandNames", All);
                    var ready = dispatcher.GetType().GetMethod("EnsureReady", All);
                    if (ready != null) ready.Invoke(dispatcher, null);
                    var n = gn == null ? null : gn.Invoke(dispatcher, null) as IEnumerable;
                    if (n != null) foreach (var x in n) names.Add(Convert.ToString(x));
                }
                foreach (var n in names.Count > 0 ? names : descs.Keys.ToList())
                {
                    Dictionary<string, object> d;
                    if (!descs.TryGetValue(n, out d)) { d = new Dictionary<string, object>(); d["name"] = n; d["description"] = ""; d["args"] = new List<object>(); }
                    else d["name"] = n;
                    list.Add(d);
                }
                var root = new Dictionary<string, object>(); root["updated"] = Iso(DateTime.Now); root["commands"] = list;
                WriteJson(Path.Combine(StateDir, "catalog.json"), root);
            }
            catch (Exception e) { Log.W("catalog: " + (e.InnerException ?? e).Message); }
        }

