        static void SyncBans(bool force)
        {
            var f = Path.Combine(Root, "bans.json");
            var stamp = File.Exists(f) ? File.GetLastWriteTimeUtc(f) : DateTime.MinValue;
            if (!force && stamp == bansStamp) return;
            bansStamp = stamp;
            var ids = BannedIds();
            WriteBanFile(ids, banFormat);
            // make sure Coop really reads our file; if not, try the other shapes once and remember the one that works
            if (ids.Count > 0 && banList != null && !IsBanned(ids[0]))
                foreach (var fmt in new[] { "object", "list", "objects" })
                {
                    WriteBanFile(ids, fmt);
                    if (IsBanned(ids[0])) { banFormat = fmt; try { File.WriteAllText(Path.Combine(StateDir, "ban-format.txt"), fmt); } catch { } WriteServerState(); Log.W("ban file format: " + fmt); break; }
                }
            foreach (var id in ids) if (online.ContainsKey(id)) { bool k; Kick(id, "اتحظرت من السيرفر", out k); }
        }

        static void WriteBanFile(List<string> ids, string fmt)
        {
            if (string.IsNullOrEmpty(banPath)) return;
            object body;
            if (fmt == "list") body = ids.Cast<object>().ToList();
            else if (fmt == "objects") body = ids.Select(x => { var d = new Dictionary<string, object>(); d["steamId"] = x; return (object)d; }).ToList();
            else { var d = new Dictionary<string, object>(); d["steamIds"] = ids.Cast<object>().ToList(); body = d; }
            try { Directory.CreateDirectory(Path.GetDirectoryName(banPath)); WriteJson(banPath, body); }
            catch (Exception e) { Log.W("ban file: " + e.Message); }
        }

