        static void PatchChat()
        {
            if (chatPatched || harmony == null) return;
            chatPatched = true;
            try
            {
                var t = AccessTools.TypeByName("Coop.Core.Server.Services.Chat.Handlers.ServerChatHandler");
                var m = t == null ? null : AccessTools.Method(t, "RouteMessage");
                sysMsg = t == null ? null : AccessTools.Method(t, "SendSystemMessage");
                if (m == null || sysMsg == null) { Log.W("AdminChat: Coop chat not found — in-game admin commands OFF"); return; }
                harmony.Patch(m, new HarmonyMethod(typeof(AdminHost).GetMethod("ChatPrefix", BindingFlags.Static | BindingFlags.Public)));
                Log.W("AdminChat: in-game admin commands ON (prefix !)");
            }
            catch (Exception e) { Log.W("AdminChat patch: " + (e.InnerException ?? e).Message); }
        }

        public static bool ChatPrefix(object __instance, object[] __args)
        {
            try
            {
                chatHandler = __instance;
                if (__args == null || __args.Length < 2) return true;
                var text = Str(Get(__args[1], "Text")).Trim();
                var peer = __args[0];
                bool cmd = text.Length >= 2 && (text[0] == '!' || text[0] == '/');
                bool uiReq = text.StartsWith("!ui", StringComparison.OrdinalIgnoreCase) && (text.Length == 3 || text[3] == ' ');
                DateTime mu;
                if (!cmd)
                {
                    var c0 = CidOfPeer(peer);
                    if (c0 != null && !admins.ContainsKey(c0) && IsMuted(c0, out mu))
                    { Say(peer, c0, "[الإدارة]  انت مكتوم في الشات" + (mu.Year > 9000 ? "." : " لحد " + mu.ToString("HH:mm", CultureInfo.InvariantCulture) + ".")); return false; }
                    return true;
                }
                var cid = CidOfPeer(peer);
                if (cid == null) return !uiReq;
                if (!admins.ContainsKey(cid))
                {
                    if (uiReq) { UiSend(peer, cid, "denied", new Dictionary<string, object>()); return false; }   // menu traffic never shows in chat
                    if (IsMuted(cid, out mu)) { Say(peer, cid, "[الإدارة]  انت مكتوم في الشات."); return false; }
                    return true;      // normal players: "!" messages are just chat
                }
                var body = uiReq ? (text.Length > 3 ? text.Substring(4).Trim() : "") : text.Substring(1).Trim();
                if (!IsAuthed(cid, peer))
                {
                    var tk0 = Tokens(body);
                    if (tk0.Count >= 2 && tk0[0].Equals("pin", StringComparison.OrdinalIgnoreCase)) TryPin(peer, cid, tk0[1], uiReq);
                    else if (uiReq) UiSend(peer, cid, "pin", PinInfo(cid, ""));
                    else Say(peer, cid, "[الإدارة]  اكتب الكود السري الأول:  !pin <الكود>   (أو دوس F10)");
                    return false;
                }
                if (uiReq) UiRequest(peer, cid, body);
                else ChatCommand(peer, cid, body);
                return false;
            }
            catch (Exception e) { Log.W("AdminChat: " + (e.InnerException ?? e).Message); return true; }
        }

        static string CidOfPeer(object peer)
        {
            if (peer == null) return null;
            foreach (var p in Players())
            {
                var cid = Str(Get(p, "ControllerId"));
                if (cid.Length == 0) continue;
                var pp = Peer(cid);
                if (pp != null && (ReferenceEquals(pp, peer) || pp.Equals(peer))) return cid;
            }
            return null;
        }

        static void Say(object peer, string cid, string text)
        {
            if (sysMsg == null || chatHandler == null || peer == null) return;
            foreach (var line in (text ?? "").Split('\n'))
                if (line.Trim().Length > 0)
                    try { sysMsg.Invoke(chatHandler, new object[] { peer, cid, line.TrimEnd() }); } catch (Exception e) { Log.W("AdminChat say: " + (e.InnerException ?? e).Message); }
        }
        public static void Broadcast(string text)
        {
            foreach (var p in Players())
            {
                var cid = Str(Get(p, "ControllerId")); var peer = Peer(cid);
                if (peer != null) Say(peer, cid, text);
            }
        }

        static List<string> Tokens(string s)
        {   // words, "quoted words" kept together
            var r = new List<string>(); var sb = new StringBuilder(); bool q = false;
            foreach (var ch in s)
            {
                if (ch == '"') { q = !q; continue; }
                if (char.IsWhiteSpace(ch) && !q) { if (sb.Length > 0) { r.Add(sb.ToString()); sb.Length = 0; } continue; }
                sb.Append(ch);
            }
            if (sb.Length > 0) r.Add(sb.ToString());
            return r;
        }

        static List<Dictionary<string, object>> OnlineSorted()
        {
            return lastList.OfType<Dictionary<string, object>>().OrderBy(x => Mj.S(x, "heroName", Mj.S(x, "platformName", "")), StringComparer.OrdinalIgnoreCase).ToList();
        }
        static string PName(Dictionary<string, object> p)
        {
            var h = Mj.S(p, "heroName", ""); var s = Mj.S(p, "platformName", "");
            return h.Length > 0 ? h + (s.Length > 0 && s != h ? " (" + s + ")" : "") : s;
        }
        // "#2" / "2" (number from !players) / Steam64 / start of the hero or Steam name
        static Dictionary<string, object> FindPlayer(string q, out string err)
        {
            err = null; var list = OnlineSorted();
            var t = q.TrimStart('#'); int n;
            if (int.TryParse(t, out n) && t.Length < 4) { if (n >= 1 && n <= list.Count) return list[n - 1]; err = "مفيش لاعب رقم " + n + " — اكتب !players"; return null; }
            var exact = list.FirstOrDefault(x => Mj.S(x, "controllerId", "") == q);
            if (exact != null) return exact;
            var m = list.Where(x => Mj.S(x, "heroName", "").StartsWith(q, StringComparison.OrdinalIgnoreCase) || Mj.S(x, "platformName", "").StartsWith(q, StringComparison.OrdinalIgnoreCase)).ToList();
            if (m.Count == 0) m = list.Where(x => Mj.S(x, "heroName", "").IndexOf(q, StringComparison.OrdinalIgnoreCase) >= 0 || Mj.S(x, "platformName", "").IndexOf(q, StringComparison.OrdinalIgnoreCase) >= 0).ToList();
            if (m.Count == 1) return m[0];
            err = m.Count == 0 ? "مفيش لاعب أونلاين اسمه \"" + q + "\" — اكتب !players" : "فيه أكتر من لاعب: " + string.Join(" ، ", m.Select(PName)) + " — استخدم الرقم من !players";
            return null;
        }
        static Dictionary<string, object> FindIn(string file, string listKey, string q)
        {
            var root = ReadJson(Path.Combine(StateDir, file)); object lo;
            if (!root.TryGetValue(listKey, out lo) || !(lo is IEnumerable)) return null;
            var all = ((IEnumerable)lo).OfType<Dictionary<string, object>>().ToList();
            return all.FirstOrDefault(x => string.Equals(Mj.S(x, "id", ""), q, StringComparison.OrdinalIgnoreCase))
                ?? all.FirstOrDefault(x => string.Equals(Mj.S(x, "name", ""), q, StringComparison.OrdinalIgnoreCase))
                ?? all.FirstOrDefault(x => Mj.S(x, "name", "").StartsWith(q, StringComparison.OrdinalIgnoreCase));
        }

        // ---------------------------------------------------------------- secret code (PIN) per admin
        //  admins.json: "pinHash" = SHA-256 of "<steam64>:<code>" (the Studio writes it). The code is asked once per connection.
        static readonly Dictionary<string, object> authed = new Dictionary<string, object>();
        static readonly Dictionary<string, int> pinFails = new Dictionary<string, int>();
        static readonly Dictionary<string, DateTime> pinLock = new Dictionary<string, DateTime>();
        public static string PinHash(string cid, string pin)
        {
            using (var sha = System.Security.Cryptography.SHA256.Create())
                return string.Concat(sha.ComputeHash(Encoding.UTF8.GetBytes((cid ?? "") + ":" + (pin ?? "").Trim())).Select(b => b.ToString("x2")));
        }
        static bool HasPin(string cid) { Dictionary<string, object> a; return admins.TryGetValue(cid ?? "", out a) && Mj.S(a, "pinHash", "").Length > 0; }
        static bool IsAuthed(string cid, object peer)
        {
            if (!HasPin(cid)) return true;      // no code set yet (the Studio shows a warning)
            object p; return authed.TryGetValue(cid, out p) && (ReferenceEquals(p, peer) || (p != null && p.Equals(peer)));
        }
        static Dictionary<string, object> PinInfo(string cid, string error)
        {
            var d = new Dictionary<string, object>(); d["name"] = AdminName(cid); d["error"] = error;
            DateTime until; d["locked"] = pinLock.TryGetValue(cid, out until) && until > DateTime.Now ? until.ToString("HH:mm", CultureInfo.InvariantCulture) : "";
            return d;
        }
        static void TryPin(object peer, string cid, string code, bool ui)
        {
            DateTime until;
            if (pinLock.TryGetValue(cid, out until) && until > DateTime.Now)
            {
                var msg = "محاولات كتير غلط — جرّب تاني بعد " + until.ToString("HH:mm", CultureInfo.InvariantCulture);
                if (ui) UiSend(peer, cid, "pin", PinInfo(cid, msg)); else Say(peer, cid, "[الإدارة]  " + msg);
                return;
            }
            Dictionary<string, object> a; admins.TryGetValue(cid, out a);
            if (a != null && string.Equals(Mj.S(a, "pinHash", ""), PinHash(cid, code), StringComparison.OrdinalIgnoreCase))
            {
                authed[cid] = peer; pinFails.Remove(cid);
                Audit(cid, AdminName(cid), "pin-ok", cid, AdminName(cid), "", true, "دخل بالكود السري");
                if (ui) UiHello(peer, cid, false); else Say(peer, cid, "[الإدارة]  ✓ الكود صح. اكتب !help أو دوس F10");
                return;
            }
            int n; pinFails.TryGetValue(cid, out n); n++; pinFails[cid] = n;
            Audit(cid, AdminName(cid), "pin-fail", cid, AdminName(cid), "", false, "كود غلط (" + n + "/3)");
            string err = "الكود غلط (" + n + " من 3)";
            if (n >= 3)
            {
                pinLock[cid] = DateTime.Now.AddMinutes(10); pinFails.Remove(cid);
                Alert("pin", cid, "محاولات كود أدمن غلط", "3 محاولات غلط لكود الأدمن " + AdminName(cid) + " (" + cid + ") من IP " + IpOf(cid) + " — اتقفل 10 دقايق. لو مش هو، حد بيحاول ينتحل شخصيته.");
                err = "3 محاولات غلط — اتقفل 10 دقايق، والإدارة اتبلّغت";
            }
            if (ui) UiSend(peer, cid, "pin", PinInfo(cid, err)); else Say(peer, cid, "[الإدارة]  " + err);
        }
        static string IpOf(string cid)
        {
            var e = lastList.OfType<Dictionary<string, object>>().FirstOrDefault(x => Mj.S(x, "controllerId", "") == cid);
            return e == null ? "?" : Mj.S(e, "ip", "?");
        }

