        static string Fmt(double v) { return v.ToString("N0", CultureInfo.InvariantCulture); }
        static string Inv(double v) { return Math.Round(v).ToString("0", CultureInfo.InvariantCulture); }

        static void ChatCommand(object peer, string cid, string line, bool ui = false)
        {
            var tk = Tokens(line);
            if (tk.Count == 0) return;
            var name = tk[0].ToLowerInvariant(); tk.RemoveAt(0);
            var perms = PermsOf(cid); var by = AdminName(cid);
            ChatCmd cmd;
            if (!ChatCmds.TryGetValue(name, out cmd)) { Reply(peer, cid, ui, false, "أمر مش معروف: !" + name + " — اكتب !help"); return; }
            if (cmd.Perm.Length > 0 && !perms.Contains(cmd.Perm)) { Reply(peer, cid, ui, false, "مش مسموحلك بالأمر ده (!" + name + ")."); Audit(cid, by, "denied:" + name, "", "", line, false, "مرفوض — مفيش صلاحية"); return; }
            if (tk.Count < cmd.Args) { Reply(peer, cid, ui, false, "الاستخدام: " + cmd.Usage); return; }
            if (Disabled.Contains(name)) { Reply(peer, cid, ui, false, "الأمر ده موقوف مؤقتاً: أوامر الممالك بتاعة Coop تجريبية وبتوقّع السيرفر. هترجع لما نلاقي طريقة آمنة."); return; }
            string err; Dictionary<string, object> p = null; string target = "", tname = "";
            bool needsPlayer = !NoPlayerCmds.Contains(name);
            if (needsPlayer)
            {
                p = FindPlayer(tk[0], out err);
                if (p == null) { Reply(peer, cid, ui, false, err); return; }
                target = Mj.S(p, "controllerId", ""); tname = PName(p);
            }
            var heroId = p == null ? "" : Mj.S(p, "heroId", ""); var heroName = p == null ? "" : Mj.S(p, "heroName", heroId);
            var rest = string.Join(" ", tk.Skip(needsPlayer ? 1 : 0));
            var arg1 = tk.Count > 1 ? tk[1] : "";
            var after1 = string.Join(" ", tk.Skip(needsPlayer ? 2 : 1));
            bool ok = true; string output;
            switch (name)
            {
                case "help":
                    Reply(peer, cid, ui, true, "أوامر الإدارة (" + by + "):\n" + string.Join("\n", ChatCmds.Values.Where(c => c.Perm.Length == 0 || perms.Contains(c.Perm)).Select(c => c.Usage + "  —  " + c.Help)) + "\nاللاعب = رقمه من !players أو أول اسمه أو Steam64.");
                    return;
                case "menu":
                    UiHello(peer, cid, false); return;
                case "players":
                    {
                        var l = OnlineSorted();
                        Reply(peer, cid, ui, true, l.Count == 0 ? "مفيش حد أونلاين." : "أونلاين (" + l.Count + "):\n" + string.Join("\n", l.Select((x, i) => "#" + (i + 1) + "  " + PName(x) + "  •  " + Mj.S(x, "clan", "") + "  •  " + Fmt(Mj.N(x, "gold", 0)) + " دينار")));
                        return;
                    }
                case "info":
                    Reply(peer, cid, ui, true, PName(p) + "\nالعشيرة: " + Mj.S(p, "clan", "—") + "  •  المملكة: " + Mj.S(p, "kingdom", "—") + "\nالفلوس: " + Fmt(Mj.N(p, "gold", 0)) + "  •  الشهرة: " + Fmt(Mj.N(p, "renown", 0)) + "  •  الجنود: " + Fmt(Mj.N(p, "troops", 0)) + "\nSteam64: " + target + (perms.Contains("ban") ? "  •  IP: " + Mj.S(p, "ip", "") : "") + "  •  تحذيرات: " + Warnings(target).Count);
                    return;
                case "kick":
                    output = Kick(target, rest.Length > 0 ? rest : "اتطردت بواسطة الإدارة", out ok); break;
                case "ban":
                    output = ServerBan(target, tname, rest, by, 0); break;
                case "tban":
                    {
                        double h; if (!double.TryParse(arg1, NumberStyles.Float, CultureInfo.InvariantCulture, out h) || h <= 0) { Reply(peer, cid, ui, false, "عدد الساعات مش صحيح"); return; }
                        output = ServerBan(target, tname, after1, by, h); break;
                    }
                case "unban":
                    output = ServerUnban(tk[0]); target = tk[0]; tname = KnownName(tk[0]); ok = output.StartsWith("✓"); break;
                case "warn":
                    {
                        var n = AddWarning(target, by, rest);
                        Say(Peer(target), target, "[تحذير من الإدارة]  " + (rest.Length > 0 ? rest : "التزم بقواعد السيرفر") + "  (التحذير رقم " + n + ")");
                        output = "✓ اتحذّر — ده التحذير رقم " + n; break;
                    }
                case "mute":
                    {
                        double m; if (!double.TryParse(arg1, NumberStyles.Float, CultureInfo.InvariantCulture, out m) || m < 0) { Reply(peer, cid, ui, false, "عدد الدقايق مش صحيح"); return; }
                        SetMute(target, m);
                        Say(Peer(target), target, "[الإدارة]  اتكتمت في الشات " + (m <= 0 ? "لحد ما الإدارة تفك الكتم" : Inv(m) + " دقيقة"));
                        output = "✓ اتكتم " + (m <= 0 ? "(دايم)" : Inv(m) + " دقيقة"); break;
                    }
                case "unmute":
                    SetMute(target, -1); Say(Peer(target), target, "[الإدارة]  اتفك الكتم عنك"); output = "✓ اتفك الكتم"; break;
                case "pm":
                    Say(Peer(target), target, "[رسالة من الإدارة — " + by + "]  " + rest); output = "✓ الرسالة وصلت"; break;
                case "say":
                    Broadcast("[إعلان من " + by + "]  " + rest); output = "✓ اتبعت لكل اللاعيبة"; break;
                case "unstuck":
                    output = Run("coop.unstuck", new List<string> { target }, out ok); break;
                case "free":
                    output = Run("coop.debug.player_captivity.release_player", new List<string> { heroId }, out ok); break;
                case "tp":
                    {
                        var st = FindIn("world.json", "settlements", rest);
                        if (st == null) { Reply(peer, cid, ui, false, "مش لاقي مدينة اسمها \"" + rest + "\""); return; }
                        output = Run("coop.debug.mobile_party.move_to_settlement", new List<string> { Mj.S(p, "partyId", ""), Mj.S(st, "id", ""), "true" }, out ok) + " ← " + Mj.S(st, "name", "");
                        break;
                    }
                case "goto":
                case "bring":
                    {
                        var me = lastList.OfType<Dictionary<string, object>>().FirstOrDefault(x => Mj.S(x, "controllerId", "") == cid);
                        if (me == null) { Reply(peer, cid, ui, false, "لازم تكون جوه الحملة بجيشك"); return; }
                        var mover = name == "goto" ? me : p; var anchor = name == "goto" ? p : me;
                        output = MoveNextTo(Mj.S(mover, "partyId", ""), Mj.S(anchor, "partyId", ""), out ok); break;
                    }
                case "gold":
                    {
                        double v; var a = arg1.Replace(",", "");
                        if (!double.TryParse(a, NumberStyles.Float, CultureInfo.InvariantCulture, out v)) { Reply(peer, cid, ui, false, "المبلغ مش رقم"); return; }
                        var h = FindHero(heroId, null); var cur = Num(Get(h, "Gold"));
                        var nv = Math.Max(0, Math.Round(a.StartsWith("+") || a.StartsWith("-") ? cur + v : v));
                        output = Run("coop.debug.hero.set_gold_state", new List<string> { heroId, Inv(nv) }, out ok) + "  (" + Fmt(cur) + " ← " + Fmt(nv) + ")";
                        break;
                    }
                case "renown":
                    output = Run("coop.debug.clan.add_renown", new List<string> { Mj.S(p, "clanId", ""), arg1.TrimStart('+') }, out ok); break;
                case "influence":
                    output = Run("coop.debug.clan.add_influence", new List<string> { Mj.S(p, "clanId", ""), arg1.TrimStart('+') }, out ok); break;
                case "skill":
                    {
                        var skills = Mj.D(p, "skills"); var sk = skills.Keys.FirstOrDefault(k => k.StartsWith(arg1, StringComparison.OrdinalIgnoreCase)) ?? arg1;
                        output = Run("coop.debug.hero_developer.set_skill", new List<string> { heroId, sk, tk[2], Inv(Mj.N(skills, sk, 0)) }, out ok);
                        break;
                    }
                case "skillreset":
                    output = Run("coop.debug.hero_developer.reset_skills", new List<string> { heroId }, out ok); break;
                case "attr":
                    output = Run("coop.debug.hero_developer.add_attribute_points", new List<string> { heroId, arg1 }, out ok); break;
                case "focus":
                    output = Run("coop.debug.hero_developer.add_focus_points", new List<string> { heroId, arg1 }, out ok); break;
                case "troops":
                    output = Run("coop.debug.mobile_party.add_troops", new List<string> { heroName }, out ok); break;
                case "troopsclear":
                    output = ClearTroops(heroId, Mj.S(p, "partyId", ""), out ok); break;
                case "troopxp":
                    output = Run("coop.debug.mobile_party.add_troop_xp", new List<string> { heroName, arg1 }, out ok); break;
                case "troopset":
                case "itemset":
                    {
                        int d; if (!int.TryParse(tk[2].Replace("+", ""), NumberStyles.Integer, CultureInfo.InvariantCulture, out d) || d == 0) { Reply(peer, cid, ui, false, "اكتب عدد زي +10 أو -5"); return; }
                        var pp = p; var what = arg1; var isTroop = name == "troopset"; var lineCopy = line;
                        OnMain(() =>
                        {
                            bool ok2; var o2 = isTroop ? TroopSet(pp, what, d, out ok2) : ItemSet(pp, what, d, out ok2);
                            ignoreUntil[target] = DateTime.UtcNow.AddSeconds(60);
                            Audit(cid, by, "chat:" + name, target, tname, lineCopy, ok2, o2);
                            Reply(peer, cid, ui, ok2, tname + ": " + o2);
                            if (ui) { nextSnap = DateTime.UtcNow.AddSeconds(2); pendingUi[cid] = peer; }
