                        return;
                    }
                case "prisoners":
                    output = Run("coop.debug.mobile_party.add_prisoners", new List<string> { heroName }, out ok); break;
                case "prisonersclear":
                    output = Run("coop.debug.mobile_party.remove_prisoners", new List<string> { heroName }, out ok); break;
