        // ---------------------------------------------------------------- Aurelion Gateway (server only)
        //  A tiny HTTP endpoint inside the server process (TCP, admin-config.json "gateway": { "port": 4201 }):
        //    GET  /status?steam64=…   → online, players, test mode (+ whether this player already has a test pass)
        //    POST /hello   {steam64,name,version,lang,state}  → the launcher checks in (Publisher shows who has it open)
        //    POST /redeem  {code,steam64,name}                → test pass for 24 h (Steam64 and IP), 5 wrong tries = 10 min lock
        //  Test mode itself is test-mode.json (written by the Publisher): when it is on, anyone who joins without a pass
        //  and isn't an admin is kicked with the test message.
        static volatile int gwPlayers;
        static System.Net.Sockets.TcpListener gw; static bool gwTried; static int gwPort = 4201;
        static readonly object gwLock = new object();
        static readonly Dictionary<string, Dictionary<string, object>> launchers = new Dictionary<string, Dictionary<string, object>>();
        static bool launchersDirty; static DateTime launchersSaved = DateTime.MinValue;
        static volatile bool testOn; static string testCode = "", testMsg = "", testMsgAr = "";
        static DateTime testStamp = DateTime.MinValue, testersStamp = DateTime.MinValue;
        static List<Dictionary<string, object>> testers = new List<Dictionary<string, object>>();
        static readonly Dictionary<string, List<DateTime>> redeemFails = new Dictionary<string, List<DateTime>>();

        static void GatewayStart()
        {
            if (gwTried) return;
            gwTried = true;
            try
            {
                var c = Mj.D(ReadJson(Path.Combine(Root, "admin-config.json")), "gateway");
                if (!Mj.B(c, "enabled", true)) { Log.W("Gateway: off (admin-config.json)"); return; }
                gwPort = (int)Mj.N(c, "port", 4201);
                gw = new System.Net.Sockets.TcpListener(System.Net.IPAddress.Any, gwPort);
                gw.Start();
                var t = new System.Threading.Thread(GatewayLoop) { IsBackground = true, Name = "AurelionGateway" };
                t.Start();
                LoadTestMode(); LoadTesters(); LoadLaunchers();
                Log.W("Gateway: listening on TCP " + gwPort + " (status / hello / redeem)");
            }
            catch (Exception e) { Log.W("Gateway: can't listen on " + gwPort + ": " + (e.InnerException ?? e).Message); }
        }

        static void GatewayLoop()
        {
            while (true)
            {
                try
                {
                    var client = gw.AcceptTcpClient();
                    System.Threading.ThreadPool.QueueUserWorkItem(o => GatewayServe((System.Net.Sockets.TcpClient)o), client);
                }
                catch (Exception e) { Log.W("Gateway accept: " + e.Message); System.Threading.Thread.Sleep(1000); }
            }
        }

        static void GatewayServe(System.Net.Sockets.TcpClient client)
        {
            try
            {
                using (client)
                {
                    client.ReceiveTimeout = 4000; client.SendTimeout = 4000;
                    var ns = client.GetStream();
                    var ip = ((System.Net.IPEndPoint)client.Client.RemoteEndPoint).Address.ToString();
                    // read the request (head + small body)
                    var buf = new byte[8192]; int len = 0, headEnd = -1, bodyLen = 0;
                    while (len < buf.Length)
                    {
                        var n = ns.Read(buf, len, buf.Length - len); if (n <= 0) break; len += n;
                        if (headEnd < 0)
                        {
                            var txt = Encoding.ASCII.GetString(buf, 0, len); headEnd = txt.IndexOf("\r\n\r\n", StringComparison.Ordinal);
                            if (headEnd >= 0)
                            {
                                var m = System.Text.RegularExpressions.Regex.Match(txt.Substring(0, headEnd), @"(?im)^content-length:\s*(\d+)");
                                bodyLen = m.Success ? Math.Min(4096, int.Parse(m.Groups[1].Value)) : 0;
                            }
                        }
                        if (headEnd >= 0 && len >= headEnd + 4 + bodyLen) break;
                    }
                    if (headEnd < 0) return;
                    var head = Encoding.ASCII.GetString(buf, 0, headEnd);
                    var first = head.Split(new[] { "\r\n" }, StringSplitOptions.None)[0].Split(' ');
                    var method = first.Length > 0 ? first[0] : ""; var target = first.Length > 1 ? first[1] : "/";
                    var body = bodyLen > 0 ? Encoding.UTF8.GetString(buf, headEnd + 4, Math.Min(bodyLen, len - headEnd - 4)) : "";
                    var path = target; var query = "";
                    var qi = target.IndexOf('?'); if (qi >= 0) { path = target.Substring(0, qi); query = target.Substring(qi + 1); }
                    object res; int code = 200;
                    try { res = GatewayHandle(method, path.ToLowerInvariant(), Query(query), body, ip, out code); }
                    catch (Exception e) { code = 500; var d = new Dictionary<string, object>(); d["error"] = e.Message; res = d; }
                    var json = Encoding.UTF8.GetBytes(Jw.Write(res));
                    var hdr = Encoding.ASCII.GetBytes("HTTP/1.1 " + code + (code == 200 ? " OK" : " Error") + "\r\nContent-Type: application/json; charset=utf-8\r\nContent-Length: " + json.Length +
                                                       "\r\nAccess-Control-Allow-Origin: *\r\nCache-Control: no-store\r\nConnection: close\r\n\r\n");
                    ns.Write(hdr, 0, hdr.Length); ns.Write(json, 0, json.Length); ns.Flush();
                }
            }
            catch { }
        }

        static Dictionary<string, string> Query(string q)
        {
            var d = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
            foreach (var part in (q ?? "").Split('&'))
            {
                var i = part.IndexOf('='); if (i <= 0) continue;
                d[Uri.UnescapeDataString(part.Substring(0, i))] = Uri.UnescapeDataString(part.Substring(i + 1).Replace('+', ' '));
            }
            return d;
        }

        static string Clean(string s, int max) { s = (s ?? "").Trim(); if (s.Length > max) s = s.Substring(0, max); return new string(s.Where(ch => !char.IsControl(ch)).ToArray()); }

        static object GatewayHandle(string method, string path, Dictionary<string, string> q, string body, string ip, out int code)
        {
            code = 200;
            if (path == "/status")
            {
                string sid; q.TryGetValue("steam64", out sid);
                return StatusFor(Clean(sid, 20), ip);
            }
            var b = (method == "POST" && body.Length > 0 ? Mj.Parse(body) as Dictionary<string, object> : null) ?? new Dictionary<string, object>();
            if (path == "/hello")
            {
                var sid = Clean(Mj.S(b, "steam64", ""), 20); if (IsSteam64(sid) == false) sid = "";
                var key = sid.Length > 0 ? sid : "ip:" + ip;
                lock (gwLock)
                {
                    Dictionary<string, object> e;
                    if (!launchers.TryGetValue(key, out e)) { e = new Dictionary<string, object>(); e["first"] = Iso(DateTime.Now); launchers[key] = e; }
                    e["steam64"] = sid; e["ip"] = ip; e["name"] = Clean(Mj.S(b, "name", ""), 40); e["version"] = Clean(Mj.S(b, "version", ""), 20);
                    e["lang"] = Clean(Mj.S(b, "lang", ""), 8); e["state"] = Clean(Mj.S(b, "state", ""), 40); e["last"] = Iso(DateTime.Now);
                    launchersDirty = true;
                }
                return StatusFor(sid, ip);
            }
            if (path == "/redeem")
            {
                var r = new Dictionary<string, object>();
                if (!testOn) { r["ok"] = true; r["note"] = "test mode is off"; return r; }
                lock (gwLock)
                {
                    List<DateTime> f; if (!redeemFails.TryGetValue(ip, out f)) redeemFails[ip] = f = new List<DateTime>();
                    f.RemoveAll(x => (DateTime.UtcNow - x).TotalMinutes > 10);
                    if (f.Count >= 5) { r["ok"] = false; r["error"] = "locked"; return r; }
                    var given = Clean(Mj.S(b, "code", ""), 32).ToUpperInvariant();
                    if (testCode.Length == 0 || !SameText(given, testCode.ToUpperInvariant())) { f.Add(DateTime.UtcNow); r["ok"] = false; r["error"] = f.Count >= 5 ? "locked" : "wrong"; r["left"] = 5 - f.Count; return r; }
                    var sid = Clean(Mj.S(b, "steam64", ""), 20); if (!IsSteam64(sid)) sid = "";
                    var t = new Dictionary<string, object>();
                    t["steam64"] = sid; t["ip"] = ip; t["name"] = Clean(Mj.S(b, "name", ""), 40); t["since"] = Iso(DateTime.Now); t["until"] = Iso(DateTime.Now.AddHours(24));
                    testers.RemoveAll(x => (sid.Length > 0 && Mj.S(x, "steam64", "") == sid) || (sid.Length == 0 && Mj.S(x, "ip", "") == ip));
                    testers.Add(t); SaveTesters();
                }
                var aSid = Clean(Mj.S(b, "steam64", ""), 20); var aName = Clean(Mj.S(b, "name", ""), 40);
                OnMain(() => Audit("system", "النظام", "test-pass", aSid, aName, "", true, "دخل كود التجربة من " + ip));
                r["ok"] = true; r["until"] = Iso(DateTime.Now.AddHours(24));
                return r;
            }
            code = 404; var nf = new Dictionary<string, object>(); nf["error"] = "not found"; return nf;
        }

        static IEnumerable<object> ListOf(Dictionary<string, object> d, string k) { object v; return d != null && d.TryGetValue(k, out v) && v is IEnumerable && !(v is string) ? ((IEnumerable)v).Cast<object>() : Enumerable.Empty<object>(); }
        static bool SameText(string a, string b)
        {
            if (a.Length != b.Length) return false;
            int diff = 0; for (int i = 0; i < a.Length; i++) diff |= a[i] ^ b[i];
            return diff == 0;
        }

        static Dictionary<string, object> StatusFor(string steam64, string ip)
        {
            var d = new Dictionary<string, object>();
            d["online"] = true; d["players"] = gwPlayers; d["maxPlayers"] = 0; d["time"] = Iso(DateTime.Now);
            var t = new Dictionary<string, object>();
            t["enabled"] = testOn; t["message"] = testMsg; t["messageAr"] = testMsgAr;
            d["test"] = t; d["tester"] = testOn && (IsTester(steam64, ip) || admins.ContainsKey(steam64 ?? ""));
            return d;
        }

        static bool IsTester(string steam64, string ip)
        {
            lock (gwLock)
                return testers.Any(x => DateTime.Now < ParseIso(Mj.S(x, "until", "")) &&
                    ((steam64 ?? "").Length > 0 && Mj.S(x, "steam64", "") == steam64 || (ip ?? "").Length > 0 && Mj.S(x, "ip", "") == ip));
        }
        static DateTime ParseIso(string s) { DateTime t; return DateTime.TryParse(s, CultureInfo.InvariantCulture, DateTimeStyles.AssumeLocal, out t) ? t : DateTime.MinValue; }

        static void LoadTestMode()
        {
            try
            {
                var f = Path.Combine(Root, "test-mode.json");
                var st = File.Exists(f) ? File.GetLastWriteTimeUtc(f) : DateTime.MinValue;
                if (st != testStamp)
                {
                    testStamp = st;
                    var d = ReadJson(f);
                    var was = testOn;
                    testCode = Mj.S(d, "code", ""); testMsg = Mj.S(d, "message", ""); testMsgAr = Mj.S(d, "messageAr", "");
                    testOn = Mj.B(d, "enabled", false) && testCode.Length > 0;
                    if (was != testOn) Log.W("Gateway: test mode " + (testOn ? "ON" : "off"));
                }
                LoadTesters();
            }
            catch (Exception e) { Log.W("Gateway test-mode: " + e.Message); }
        }
        static void LoadTesters()
        {
            var f = Path.Combine(Root, "testers.json");
            var st = File.Exists(f) ? File.GetLastWriteTimeUtc(f) : DateTime.MinValue;
            if (st == testersStamp) return;
            testersStamp = st;
            var l = ListOf(ReadJson(f), "testers").OfType<Dictionary<string, object>>().ToList();
            lock (gwLock) testers = l;
        }
        static void SaveTesters()
        {
            var d = new Dictionary<string, object>();
            d["testers"] = testers.Where(x => DateTime.Now < ParseIso(Mj.S(x, "until", ""))).Cast<object>().ToList();
            WriteJson(Path.Combine(Root, "testers.json"), d);
            testersStamp = File.GetLastWriteTimeUtc(Path.Combine(Root, "testers.json"));
        }
        static void LoadLaunchers()
        {
            foreach (var x in ListOf(ReadJson(Path.Combine(StateDir, "launchers.json")), "launchers").OfType<Dictionary<string, object>>())
            {
                var k = Mj.S(x, "steam64", ""); if (k.Length == 0) k = "ip:" + Mj.S(x, "ip", "");
                lock (gwLock) launchers[k] = x;
            }
        }
        static void SaveLaunchers(bool force)
        {
            if (!launchersDirty && !force) return;
            if (!force && (DateTime.UtcNow - launchersSaved).TotalSeconds < 10) return;
            launchersSaved = DateTime.UtcNow;
            List<object> l;
            lock (gwLock)
            {
                launchersDirty = false;
                // keep 30 days, newest first
                foreach (var k in launchers.Where(kv => (DateTime.Now - ParseIso(Mj.S(kv.Value, "last", ""))).TotalDays > 30).Select(kv => kv.Key).ToList()) launchers.Remove(k);
                l = launchers.Values.OrderByDescending(x => Mj.S(x, "last", "")).Select(x => (object)new Dictionary<string, object>(x)).ToList();
            }
            var d = new Dictionary<string, object>(); d["updated"] = Iso(DateTime.Now); d["launchers"] = l;
            WriteJson(Path.Combine(StateDir, "launchers.json"), d);
        }

        // someone joined while the server is in test mode
        static void TestGate(string cid, string ip, string name)
        {
            if (!testOn || admins.ContainsKey(cid) || IsTester(cid, ip)) return;
            bool ok; var why = testMsgAr.Length > 0 ? testMsgAr : "السيرفر في وضع تجربة للإداريين والمختبرين بس. ادخل كود التجربة من اللانشر.";
            Kick(cid, why, out ok);
            Audit("system", "النظام", "test-kick", cid, name, "", ok, "اتطرد لأن السيرفر في وضع تجربة (" + ip + ")");
        }

        // ---------------------------------------------------------------- performance probes (server and players)
        //  Measures the campaign's periodic ticks and any frame that takes over 0.75 s, and writes them to aurelion.log
        //  ("Perf: ..."). Used to find the short freezes players see every minute or so.
        static readonly System.Diagnostics.Stopwatch perfFrameSw = new System.Diagnostics.Stopwatch();
        static int perfLogged; static DateTime perfWindow = DateTime.UtcNow;
        static void PerfSetup()
        {
            try
            {
                var t = AccessTools.TypeByName("TaleWorlds.CampaignSystem.CampaignPeriodicEventManager");
                var pre = new HarmonyMethod(typeof(AdminHost).GetMethod("PerfPrefix", BindingFlags.Static | BindingFlags.Public));
                var post = new HarmonyMethod(typeof(AdminHost).GetMethod("PerfPostfix", BindingFlags.Static | BindingFlags.Public));
                int n = 0;
                if (t != null)
                    foreach (var name in new[] { "PeriodicDailyTick", "PeriodicHourlyTick", "PeriodicQuarterDailyTick", "TickPeriodicEvents" })
                    {
                        var m = AccessTools.Method(t, name);
                        if (m != null) { harmony.Patch(m, pre, post); n++; }
                    }
                Log.W("Perf: probes on " + n + " campaign tick methods (logs ticks > 0.25 s and frames > 0.75 s)");
            }
            catch (Exception e) { Log.W("Perf setup: " + (e.InnerException ?? e).Message); }
        }
        public static void PerfPrefix(out long __state) { __state = System.Diagnostics.Stopwatch.GetTimestamp(); }
        public static void PerfPostfix(long __state, MethodBase __originalMethod)
        {
            try
            {
                var ms = (System.Diagnostics.Stopwatch.GetTimestamp() - __state) * 1000.0 / System.Diagnostics.Stopwatch.Frequency;
                if (ms >= 250) PerfLog(__originalMethod.Name + " took " + ms.ToString("0") + " ms");
            }
            catch { }
        }
        static void PerfFrame()
        {
            try
            {
                if (perfFrameSw.IsRunning)
                {
                    var ms = perfFrameSw.Elapsed.TotalMilliseconds;
                    if (ms >= 750) PerfLog("frame stall " + ms.ToString("0") + " ms");
                }
                perfFrameSw.Reset(); perfFrameSw.Start();
            }
            catch { }
        }
        static void PerfLog(string what)
        {
            if ((DateTime.UtcNow - perfWindow).TotalMinutes >= 10) { perfWindow = DateTime.UtcNow; perfLogged = 0; }
            if (++perfLogged > 200) return;
            string date = "";
            try { var ct = AccessTools.TypeByName("TaleWorlds.CampaignSystem.CampaignTime"); date = Str(Get(ct, "Now")); } catch { }
            Log.W("Perf: " + what + (date.Length > 0 ? "  @ " + date : "") + (isServer ? "  [server]" : "  [player]"));
        }

        // ---------------------------------------------------------------- time: always running at normal speed
        //  Coop (v0.1.7) lets every player pause / fast-forward, pauses when nobody is connected and when all players sit in towns.
        //  Owner's rule (2026-11-07): the campaign clock never stops and runs at 1x, with or without players.
        //   - TimeHandler.Handle_NetworkRequestTimeSpeedChange  → ignored (players can't change time)
        //   - DisconnectedPlayersServerHandler.PlayersConnectedPolicy → always "allowed"; PauseWhenNoPlayersConnected → skipped
        //   - every 4 s: if the campaign isn't playing, ask Coop for Play_1x (Coop's own catch-up protection still applies)
        //  Switch off: admin-config.json  "time": { "always": false }
        static bool timePatched; static int timeBlocked, timeFixes; static string lastTimeMode = ""; static DateTime timeQuietUntil = DateTime.MinValue;
        public static bool TimeRequestPrefix() { if (!cfg.AlwaysTime) return true; timeBlocked++; return false; }
        public static void TimeAllowPostfix(ref bool __result) { if (cfg.AlwaysTime) __result = true; }
        public static bool TimeSkipPrefix() { return !cfg.AlwaysTime; }

        static void TimeSetup()
        {
            if (timePatched || harmony == null) return;
            timePatched = true;
            var st = BindingFlags.Static | BindingFlags.Public;
            try
            {
                var th = AccessTools.TypeByName("Coop.Core.Server.Services.Time.Handlers.TimeHandler");
                var req = th == null ? null : AccessTools.Method(th, "Handle_NetworkRequestTimeSpeedChange");
                if (req != null) harmony.Patch(req, new HarmonyMethod(typeof(AdminHost).GetMethod("TimeRequestPrefix", st)));
                var dh = AccessTools.TypeByName("Coop.Core.Server.Services.Players.Handlers.DisconnectedPlayersServerHandler");
                var pol = dh == null ? null : AccessTools.Method(dh, "PlayersConnectedPolicy");
                if (pol != null && pol.ReturnType == typeof(bool)) harmony.Patch(pol, null, new HarmonyMethod(typeof(AdminHost).GetMethod("TimeAllowPostfix", st)));
                var pw = dh == null ? null : AccessTools.Method(dh, "PauseWhenNoPlayersConnected");
                if (pw != null) harmony.Patch(pw, new HarmonyMethod(typeof(AdminHost).GetMethod("TimeSkipPrefix", st)));
                Log.W("AdminTime: player time requests " + (req != null ? "blocked" : "NOT FOUND") + ", no-players pause " + (pol != null && pw != null ? "off" : "NOT FOUND") + " (always=" + cfg.AlwaysTime + ")");
            }
            catch (Exception e) { Log.W("AdminTime setup: " + (e.InnerException ?? e).Message); }
        }

        static string CampaignMode()
        {
            var ct = AccessTools.TypeByName("TaleWorlds.CampaignSystem.Campaign");
            var c = Get(ct, "Current");
            return c == null ? "" : Str(Get(c, "TimeControlMode"));
        }

        static void TimeKeep()
        {
            TimeSetup();
            if (!cfg.AlwaysTime || dispatcher == null) return;
            var mode = CampaignMode();
            if (mode.Length == 0) return;
            if (mode != lastTimeMode) { Log.W("AdminTime: campaign mode " + (lastTimeMode.Length == 0 ? "" : lastTimeMode + " → ") + mode + (timeBlocked > 0 ? "  (player requests ignored so far: " + timeBlocked + ")" : "")); lastTimeMode = mode; }
            if (mode.IndexOf("Play", StringComparison.OrdinalIgnoreCase) >= 0 && mode.IndexOf("FastForward", StringComparison.OrdinalIgnoreCase) < 0) return;
            bool ok; var r = Run("coop.debug.set_time_mode", new List<string> { "Play_1x" }, out ok);
            timeFixes++;
            if (DateTime.UtcNow >= timeQuietUntil) { Log.W("AdminTime: " + mode + " → Play_1x: " + r); timeQuietUntil = DateTime.UtcNow.AddMinutes(5); }
        }

        // ---------------------------------------------------------------- work that must run on the game thread
        static readonly Queue<Action> mainQueue = new Queue<Action>();
        static void OnMain(Action a) { lock (mainQueue) mainQueue.Enqueue(a); }
        static void RunMainQueue()
        {
            for (int i = 0; i < 20; i++)
            {
                Action a;
                lock (mainQueue) { if (mainQueue.Count == 0) return; a = mainQueue.Dequeue(); }
                try { a(); } catch (Exception e) { Log.W("AdminHost main-thread job: " + (e.InnerException ?? e)); }
            }
        }

        // ---------------------------------------------------------------- troops of a chosen type / items in the bag
        static object ObjectById(string typeName, string id)
        {
            try
            {
                var t = AccessTools.TypeByName(typeName); if (t == null || string.IsNullOrEmpty(id)) return null;
                var mgrType = AccessTools.TypeByName("TaleWorlds.ObjectSystem.MBObjectManager");
                var mgr = Get(mgrType, "Instance");
                var gm = mgrType.GetMethods(BindingFlags.Instance | BindingFlags.Public).FirstOrDefault(m => m.Name == "GetObject" && m.IsGenericMethodDefinition && m.GetParameters().Length == 1 && m.GetParameters()[0].ParameterType == typeof(string));
                return gm == null ? null : gm.MakeGenericMethod(t).Invoke(mgr, new object[] { id });
            }
            catch { return null; }
        }
        static object PartyOf(Dictionary<string, object> p)
        {
            var hero = FindHero(Mj.S(p, "heroId", ""), null);
            var party = Get(hero, "PartyBelongedTo");
            if (party != null) return party;
            var mpType = AccessTools.TypeByName("TaleWorlds.CampaignSystem.Party.MobileParty");
            var pid = Mj.S(p, "partyId", "");
            return pid.Length == 0 ? null : (CoopObject(mpType, pid) ?? Scan(Get(mpType, "All") as IEnumerable, pid));
        }

        static string TroopSet(Dictionary<string, object> p, string charId, int delta, out bool ok)
        {
            ok = false;
            var ch = ObjectById("TaleWorlds.CampaignSystem.CharacterObject", charId);
            if (ch == null) return "نوع الجندي ده مش موجود: " + charId;
            if (Get(ch, "IsHero") is bool && (bool)Get(ch, "IsHero")) return "ده بطل مش جندي";
            var party = PartyOf(p); var roster = Get(party, "MemberRoster");
            if (roster == null) return "مش لاقي جيشه";
            int cur = 0, wounded = 0, xp = 0;
            var m = roster.GetType().GetMethods(All).FirstOrDefault(x => x.Name == "GetTroopRoster" && x.GetParameters().Length == 0);
            var list = m == null ? null : m.Invoke(roster, null) as IEnumerable;
            if (list != null)
                foreach (var el in list)
                {
                    var c = Get(el, "Character");
                    if (c == null || Str(Get(c, "StringId")) != charId) continue;
                    cur = (int)Num(Get(el, "Number")); wounded = (int)Num(Get(el, "WoundedNumber")); xp = (int)Num(Get(el, "Xp"));
                }
            var n = Math.Max(0, Math.Min(5000, cur + delta));
            if (n == cur) { ok = true; return "مفيش تغيير (" + cur + ")"; }
            var pid = Str(Get(party, "StringId")); if (pid.Length == 0) pid = Mj.S(p, "partyId", "");
            var r = Run("coop.debug.mobile_party.set_troop_state", new List<string> { pid, charId, n > 0 ? "true" : "false", Inv(n), Inv(Math.Min(wounded, n)), Inv(n > 0 ? xp : 0) }, out ok);
            return (ok ? "✓ " : "") + Str(Get(ch, "Name")) + ": " + cur + " ← " + n + (ok ? "" : "  " + r);
        }

        static string ItemSet(Dictionary<string, object> p, string itemId, int delta, out bool ok)
        {
            ok = false;
            var item = ObjectById("TaleWorlds.Core.ItemObject", itemId);
            if (item == null) return "الحاجة دي مش موجودة: " + itemId;
            var party = PartyOf(p); var roster = Get(party, "ItemRoster");
            if (roster == null) return "مش لاقي شنطته";
            var it = item.GetType();
            var num = roster.GetType().GetMethods(All).FirstOrDefault(x => x.Name == "GetItemNumber" && x.GetParameters().Length == 1 && x.GetParameters()[0].ParameterType.IsAssignableFrom(it));
            int cur = num == null ? 0 : Convert.ToInt32(num.Invoke(roster, new[] { item }));
            if (delta < 0) delta = Math.Max(delta, -cur);
            if (delta == 0) { ok = true; return "مفيش منها في الشنطة"; }
            var add = roster.GetType().GetMethods(All).FirstOrDefault(x => x.Name == "AddToCounts" && x.GetParameters().Length == 2 && x.GetParameters()[0].ParameterType.IsAssignableFrom(it) && x.GetParameters()[1].ParameterType == typeof(int));
            if (add == null) return "مش قادر أضيف للشنطة (AddToCounts)";
            add.Invoke(roster, new object[] { item, delta });   // Coop's ItemRosterPatch sends this to every client
            ok = true;
            return "✓ " + Str(Get(item, "Name")) + ": " + cur + " ← " + (cur + delta);
        }

        // ---------------------------------------------------------------- troops / moving
        static string ClearTroops(string heroId, string partyId, out bool ok)
        {
            ok = false;
            var hero = FindHero(heroId, null); var party = Get(hero, "PartyBelongedTo");
            var roster = Get(party, "MemberRoster");
            if (roster == null) return "مش لاقي جيشه";
            var m = roster.GetType().GetMethods(All).FirstOrDefault(x => x.Name == "GetTroopRoster" && x.GetParameters().Length == 0);
            var list = m == null ? null : m.Invoke(roster, null) as IEnumerable;
            if (list == null) return "مش قادر أقرا الجنود";
            int n = 0, fail = 0; string last = "";
            foreach (var el in list.Cast<object>().ToList())
            {
                var ch = Get(el, "Character");
                if (ch == null || (Get(ch, "IsHero") is bool && (bool)Get(ch, "IsHero"))) continue;
                bool k; last = Run("coop.debug.mobile_party.set_troop_state", new List<string> { partyId, Str(Get(ch, "StringId")), "false", "0", "0", "0" }, out k);
                if (k) n++; else fail++;
            }
            ok = fail == 0;
            return (n > 0 ? "✓ اتشال " + n + " نوع جنود" : "") + (fail > 0 ? "  ✗ " + fail + " فشلوا: " + last : "") + (n == 0 && fail == 0 ? "مفيش جنود" : "");
        }

        static bool PartyPos(object party, out double x, out double y)
        {
            x = y = 0;
            foreach (var pn in new[] { "Position2D", "Position", "VisualPosition2DWithoutError" })
            {
                var pos = Get(party, pn); if (pos == null) continue;
                var v = Get(pos, "ToVec2") ?? pos;
                var mx = pos.GetType().GetMethod("ToVec2", Type.EmptyTypes); if (mx != null) try { v = mx.Invoke(pos, null); } catch { }
                var ox = Get(v, "x") ?? Get(v, "X"); var oy = Get(v, "y") ?? Get(v, "Y");
                if (ox != null && oy != null) { x = Num(ox); y = Num(oy); return true; }
            }
            return false;
        }
        static string MoveNextTo(string fromParty, string toParty, out bool ok)
        {
            ok = false;
            var mpType = AccessTools.TypeByName("TaleWorlds.CampaignSystem.Party.MobileParty");
            var to = CoopObject(mpType, toParty) ?? Scan(Get(mpType, "All") as IEnumerable, toParty);
            double x, y;
            if (to == null || !PartyPos(to, out x, out y)) return "مش عارف أجيب مكان الجيش";
            return Run("coop.debug.mobile_party.restore_position", new List<string> { fromParty, (x + 0.6).ToString("0.###", CultureInfo.InvariantCulture), y.ToString("0.###", CultureInfo.InvariantCulture), "true" }, out ok);
        }

        static string ServerBan(string target, string tname, string reason, string by, double hours)
        {
            var f = Path.Combine(Root, "bans.json");
            var root = ReadJson(f); object lo;
            var list = root.TryGetValue("bans", out lo) && lo is IEnumerable ? ((IEnumerable)lo).Cast<object>().Where(x => !(x is Dictionary<string, object>) || Mj.S((Dictionary<string, object>)x, "controllerId", "") != target).ToList() : new List<object>();
            var d = new Dictionary<string, object>();
            d["controllerId"] = target; d["name"] = tname; d["reason"] = reason; d["by"] = by; d["time"] = DateTime.Now.ToString("yyyy-MM-dd HH:mm", CultureInfo.InvariantCulture);
            if (hours > 0) d["until"] = DateTime.Now.AddHours(hours).ToString("yyyy-MM-dd HH:mm", CultureInfo.InvariantCulture);
            list.Add(d);
            var r = new Dictionary<string, object>(); r["bans"] = list;
            WriteJson(f, r);
            SyncBans(true);
            return hours > 0 ? "✓ اتحظر " + Inv(hours) + " ساعة واتطرد" : "✓ اتحظر واتطرد";
        }
        static string ServerUnban(string target)
        {
            var f = Path.Combine(Root, "bans.json");
            var root = ReadJson(f); object lo;
            var list = root.TryGetValue("bans", out lo) && lo is IEnumerable ? ((IEnumerable)lo).Cast<object>().ToList() : new List<object>();
            var before = list.Count;
            list = list.Where(x => !(x is Dictionary<string, object>) || Mj.S((Dictionary<string, object>)x, "controllerId", "") != target).ToList();
            if (list.Count == before) return "الرقم ده مش محظور";
            var r = new Dictionary<string, object>(); r["bans"] = list;
            WriteJson(f, r);
            SyncBans(true);
            return "✓ اتفك الحظر";
        }

        // ==================================================================== in-game menu channel
        //  menu → server : chat text "!ui <verb> ..."  (never shown to anyone)
        //  server → menu : system message "\u0001AUR|<kind>|<json>"  (the menu hides it from the chat)
        public const string UiMarker = "\u0001AUR|";
        static readonly Dictionary<string, object> pendingUi = new Dictionary<string, object>();

        static void UiSend(object peer, string cid, string kind, object data)
        {
            if (sysMsg == null || chatHandler == null || peer == null) return;
            try { sysMsg.Invoke(chatHandler, new object[] { peer, cid, UiMarker + kind + "|" + Jw.Write(data) }); }
            catch (Exception e) { Log.W("AdminUi send: " + (e.InnerException ?? e).Message); }
        }

        static Dictionary<string, object> UiPlayer(Dictionary<string, object> x, HashSet<string> perms)
        {
            var d = new Dictionary<string, object>(x);
            if (!perms.Contains("ban")) { d.Remove("ip"); d.Remove("port"); }
            var cid = Mj.S(x, "controllerId", "");
            d["warnings"] = Warnings(cid).Count;
            DateTime mu; d["muted"] = IsMuted(cid, out mu) ? (mu.Year > 9000 ? "دايم" : mu.ToString("HH:mm", CultureInfo.InvariantCulture)) : "";
            d["isAdmin"] = admins.ContainsKey(cid);
            return d;
        }

        static void UiPlayers(object peer, string cid)
        {
            var perms = PermsOf(cid);
            var d = new Dictionary<string, object>();
            d["players"] = OnlineSorted().Select(x => (object)UiPlayer(x, perms)).ToList();
            UiSend(peer, cid, "players", d);
        }

        static void UiHello(object peer, string cid, bool lite)
        {
            Dictionary<string, object> a; admins.TryGetValue(cid, out a);
            var me = new Dictionary<string, object>();
            me["name"] = AdminName(cid); me["cid"] = cid; me["level"] = a == null ? "" : Mj.S(a, "level", "observer"); me["perms"] = PermsOf(cid).Cast<object>().ToList();
            var w = ReadJson(Path.Combine(StateDir, "world.json"));
            var d = new Dictionary<string, object>();
            d["me"] = me;
            object so, ko;
            d["settlements"] = lite ? new List<object>() : w.TryGetValue("settlements", out so) && so is IEnumerable ? ((IEnumerable)so).OfType<Dictionary<string, object>>().Where(x => Mj.S(x, "type", "") != "village").Cast<object>().ToList() : new List<object>();
            d["kingdoms"] = w.TryGetValue("kingdoms", out ko) ? ko : new List<object>();
            UiSend(peer, cid, "hello", d);
            UiPlayers(peer, cid);
        }

        static void UiRequest(object peer, string cid, string rest)
        {
            var tk = Tokens(rest);
            var verb = tk.Count > 0 ? tk[0].ToLowerInvariant() : "hello";
            var perms = PermsOf(cid);
            switch (verb)
            {
                case "hello": UiHello(peer, cid, tk.Count > 1 && tk[1] == "lite"); break;
                case "world":
                    {
                        // fallback when the admin's own campaign can't be read: send every settlement in small parts
                        var w = ReadJson(Path.Combine(StateDir, "world.json")); object so;
                        var all = w.TryGetValue("settlements", out so) && so is IEnumerable ? ((IEnumerable)so).OfType<Dictionary<string, object>>().ToList() : new List<Dictionary<string, object>>();
                        const int part = 60; int parts = Math.Max(1, (all.Count + part - 1) / part);
                        for (int i = 0; i < parts; i++)
                        {
                            var d = new Dictionary<string, object>(); d["part"] = i; d["parts"] = parts;
                            d["items"] = all.Skip(i * part).Take(part).Select(x => (object)(Mj.S(x, "id", "") + "\t" + Mj.S(x, "type", "") + "\t" + Mj.S(x, "name", "") + "\t" + Mj.S(x, "owner", "") + "\t" + Mj.S(x, "kingdom", "") + "\t" + Mj.S(x, "kingdomId", ""))).ToList();
                            UiSend(peer, cid, "world", d);
                        }
                        break;
                    }
                case "players": UiPlayers(peer, cid); break;
                case "do": ChatCommand(peer, cid, string.Join(" ", tk.Skip(1).Select(x => x.IndexOf(' ') >= 0 ? "\"" + x + "\"" : x)), true); break;
                case "bans":
                    {
                        if (!perms.Contains("ban")) { UiSend(peer, cid, "bans", new Dictionary<string, object>()); break; }
                        var root = ReadJson(Path.Combine(Root, "bans.json")); object lo;
                        var d = new Dictionary<string, object>(); d["bans"] = root.TryGetValue("bans", out lo) ? lo : new List<object>();
                        UiSend(peer, cid, "bans", d); break;
                    }
                case "log":
                    {
                        var lines = new List<object>();
                        try
                        {
                            var f = Path.Combine(Root, "audit.jsonl");
                            if (File.Exists(f))
                                foreach (var l in File.ReadAllLines(f, Encoding.UTF8).Reverse().Where(x => x.Trim().Length > 0).Take(40))
                                {
                                    var h = Mj.Parse(l) as Dictionary<string, object>; if (h == null) continue;
                                    var s = new Dictionary<string, object>();
                                    foreach (var k in new[] { "time", "byName", "action", "targetName", "reason", "output", "ok" }) { object v; if (h.TryGetValue(k, out v)) s[k] = v; }
                                    lines.Add(s);
                                }
                        }
                        catch { }
                        var d = new Dictionary<string, object>(); d["lines"] = lines;
                        UiSend(peer, cid, "log", d); break;
                    }
            }
        }

        static void FlushPendingUi()
        {
            if (pendingUi.Count == 0) return;
            foreach (var kv in pendingUi.ToList()) { var pr = Peer(kv.Key); if (pr != null) UiPlayers(pr, kv.Key); }
            pendingUi.Clear();
        }

        // ------------------------------------------------------------------ audit log
        static void Audit(string by, string byName, string action, string target, string targetName, string reason, bool ok, string output, string id = "", Dictionary<string, object> cmd = null)
        {
            var d = new Dictionary<string, object>();
            d["time"] = Iso(DateTime.Now); d["id"] = id; d["by"] = by; d["byName"] = byName; d["action"] = action;
            d["target"] = target; d["targetName"] = targetName; d["reason"] = reason; d["ok"] = ok; d["output"] = output ?? "";
            if (cmd != null) { object a; if (cmd.TryGetValue("args", out a)) d["args"] = a; object l; if (cmd.TryGetValue("label", out l)) d["label"] = l; }
            AppendLine(Path.Combine(Root, "audit.jsonl"), d);
        }

        // ------------------------------------------------------------------ small helpers
        public static object Get(object o, string name)
        {
            if (o == null) return null;
            var t = o as Type ?? o.GetType(); var inst = o is Type ? null : o;
            for (var x = t; x != null; x = x.BaseType)
            {
                var p = x.GetProperty(name, All | BindingFlags.DeclaredOnly);
                if (p != null && p.GetIndexParameters().Length == 0) { try { return p.GetValue(inst, null); } catch { return null; } }
                var f = x.GetField(name, All | BindingFlags.DeclaredOnly);
                if (f != null) { try { return f.GetValue(inst); } catch { return null; } }
            }
            return null;
        }
        static string Str(object o) { return o == null ? "" : Convert.ToString(o, CultureInfo.InvariantCulture); }
        static double Num(object o) { try { return o == null ? 0 : Convert.ToDouble(o, CultureInfo.InvariantCulture); } catch { return 0; } }
        static bool IsSteam64(string s) { ulong v; return s != null && s.Length == 17 && s.StartsWith("7656") && ulong.TryParse(s, out v); }
        static string Iso(DateTime t) { return t.ToString("yyyy-MM-dd HH:mm:ss", CultureInfo.InvariantCulture); }

        static Dictionary<string, object> ReadJson(string path)
        {
            try { if (File.Exists(path)) return Mj.Parse(File.ReadAllText(path, Encoding.UTF8)) as Dictionary<string, object> ?? new Dictionary<string, object>(StringComparer.OrdinalIgnoreCase); }
            catch (Exception e) { Log.W("read " + path + ": " + e.Message); }
            return new Dictionary<string, object>(StringComparer.OrdinalIgnoreCase);
        }
        static void WriteJson(string path, object o)
        {
            try
            {
                Directory.CreateDirectory(Path.GetDirectoryName(path));
                var tmp = path + ".tmp";
                File.WriteAllText(tmp, Jw.Write(o), new UTF8Encoding(false));
                if (File.Exists(path)) File.Replace(tmp, path, null); else File.Move(tmp, path);
            }
            catch (Exception e) { Log.W("write " + path + ": " + e.Message); }
        }
        static void AppendLine(string path, object o)
        {
            try { Directory.CreateDirectory(Path.GetDirectoryName(path)); File.AppendAllText(path, Jw.Write(o) + "\n", new UTF8Encoding(false)); }
            catch (Exception e) { Log.W("append " + path + ": " + e.Message); }
        }
    }

    // ---------------------------------------------------------------- tiny JSON writer (one line)
    public static class Jw
    {
        public static string Write(object o) { var sb = new StringBuilder(); W(sb, o); return sb.ToString(); }
        static void W(StringBuilder sb, object o)
        {
            if (o == null) { sb.Append("null"); return; }
            if (o is string) { S(sb, (string)o); return; }
            if (o is bool) { sb.Append((bool)o ? "true" : "false"); return; }
            if (o is IDictionary<string, object>)
            {
                sb.Append('{'); bool first = true;
                foreach (var kv in (IDictionary<string, object>)o) { if (!first) sb.Append(','); first = false; S(sb, kv.Key); sb.Append(':'); W(sb, kv.Value); }
                sb.Append('}'); return;
            }
            if (o is IEnumerable)
            {
                sb.Append('['); bool first = true;
                foreach (var x in (IEnumerable)o) { if (!first) sb.Append(','); first = false; W(sb, x); }
                sb.Append(']'); return;
            }
            if (o is double || o is float || o is decimal) { var d = Convert.ToDouble(o); sb.Append(double.IsNaN(d) || double.IsInfinity(d) ? "0" : d.ToString("0.######", CultureInfo.InvariantCulture)); return; }
            if (o.GetType().IsPrimitive) { sb.Append(Convert.ToString(o, CultureInfo.InvariantCulture)); return; }
            S(sb, Convert.ToString(o, CultureInfo.InvariantCulture));
        }
        static void S(StringBuilder sb, string s)
        {
            sb.Append('"');
            foreach (var c in s)
            {
                if (c == '"') sb.Append("\\\""); else if (c == '\\') sb.Append("\\\\");
                else if (c == '\n') sb.Append("\\n"); else if (c == '\r') sb.Append("\\r"); else if (c == '\t') sb.Append("\\t");
                else if (c < 0x20) sb.Append("\\u").Append(((int)c).ToString("x4"));
                else sb.Append(c);
            }
            sb.Append('"');
        }
    }
