// =====================================================================================
//  system/RulesGate.cs — مفتاح تشغيل قواعد اللعب كلها
//  ملف نظام: الاستوديو بيكتبه من جديد مع كل بناء. متعدّلش فيه.
//  قواعد اللعب (حد المهارات، سرعة الخبرة والشهرة، أسعار السوق) مش بتشتغل غير لما
//  "شغّل قواعد اللعب" يبقى متعلّم في صفحة قواعد اللعب في الاستوديو.
// =====================================================================================
using System;
using System.IO;
using System.Reflection;
using System.Text;

namespace Aurelion.Core
{
    public static class RulesGate
    {
        public static bool Enabled
        {
            get
            {
                try
                {
                    var dir = Path.GetFullPath(Path.Combine(Path.GetDirectoryName(Assembly.GetExecutingAssembly().Location), "..", "..", "aurelion"));
                    var f = Path.Combine(dir, "rules.json");
                    if (!File.Exists(f)) return false;
                    var d = Mj.Parse(File.ReadAllText(f, Encoding.UTF8)) as System.Collections.Generic.Dictionary<string, object>;
                    return Mj.B(d, "enabled", false);
                }
                catch { return false; }
            }
        }
    }
}
